                    modifier = Modifier.fillMaxWidth()
                )
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        if (renameValue.isNotBlank()) onRename(target.id, renameValue)
                        renameTarget = null
                    }
                ) { Text("확인") }
            },
            dismissButton = {
                TextButton(onClick = { renameTarget = null }) { Text("취소") }
            }
        )
    }

    deleteTarget?.let { target ->
        AlertDialog(
            onDismissRequest = { deleteTarget = null },
            title = { Text("체크리스트 삭제") },
            text = { Text("'${target.title}'을 삭제합니다.") },
            confirmButton = {
                TextButton(onClick = {
                    val moved = onDeleteToTrash(target.id)
                    if (!moved) {
                        Toast.makeText(
                            context,
                            "휴지통으로 이동하지 못했습니다.",
                            Toast.LENGTH_SHORT
                        ).show()
                    }
                    deleteTarget = null
                }) { Text("삭제") }
            },
            dismissButton = {
                TextButton(onClick = { deleteTarget = null }) { Text("취소") }
            }
        )
    }
}

private fun progressText(p: ChecklistProgress): String =
    if (p.effectiveItems == 0) {
        "진행 대상 없음 · 해당 없음 ${p.notApplicableItems}"
    } else {
        "완료 ${p.completeItems} / 미완료 ${p.incompleteItems} / 해당 없음 ${p.notApplicableItems} · ${p.completionPercent}%"
    }

@Composable
private fun ChecklistDetailScreen(
    checklist: Checklist,
    onBack: () -> Unit,
    onHome: () -> Unit,
    onResult: () -> Unit,
    onRename: (String) -> Unit,
    onAddItem: (String, String, String?, Boolean, Int?, String?) -> Unit,
    onEditItem: (String, String, String, String?, Boolean, Int?, String?) -> Unit,
    onDeleteItem: (String) -> Unit,
    onRestoreItem: (String) -> Unit,
    onPermanentlyDeleteItem: (String) -> Unit,
    onStatus: (String, ChecklistStatus) -> Unit,
    onAddGroup: (String, String) -> Unit,
    onGroupColor: (String, String) -> Unit,
    onDeleteGroup: (String) -> Unit,
    onAssignGroup: (Set<String>, String?) -> Unit,
    onPickNotificationSound: (String?, (String) -> Unit) -> Unit,
    onBulkNotificationSound: (String?) -> Unit,
    onMemo: (String) -> Unit,
    onReset: () -> Unit,
    onReorder: (List<String>) -> Boolean
) {
    val context = LocalContext.current
    var titleEdit by rememberSaveable { mutableStateOf(false) }
    var addingItem by rememberSaveable { mutableStateOf(false) }
    var editingItem by remember { mutableStateOf<ChecklistItem?>(null) }
    var groupManager by rememberSaveable { mutableStateOf(false) }
    var groupPicker by rememberSaveable { mutableStateOf(false) }
    var memoEdit by rememberSaveable { mutableStateOf(false) }
    var resetConfirm by rememberSaveable { mutableStateOf(false) }
    var deleteTarget by remember { mutableStateOf<ChecklistItem?>(null) }
    var trashOpen by rememberSaveable { mutableStateOf(false) }
    var permanentDeleteTarget by remember { mutableStateOf<ChecklistItem?>(null) }
    var viewMode by remember { mutableStateOf(ChecklistViewMode.DETAIL) }
    var voiceDrafts by remember { mutableStateOf<List<ChecklistVoiceDraft>?>(null) }
    var voiceMessage by remember { mutableStateOf<String?>(null) }
    var headerMenuOpen by remember { mutableStateOf(false) }

    var assignmentGroupId by rememberSaveable { mutableStateOf<String?>(null) }
    var assignmentUngroup by rememberSaveable { mutableStateOf(false) }
    var selectedIdList by rememberSaveable { mutableStateOf(emptyList<String>()) }
    val selectedIds = selectedIdList.toSet()

    val haptic = LocalHapticFeedback.current
    val listState = rememberLazyListState()
    val canonicalItems = remember(checklist.items) { checklist.items.sortedBy { it.order } }
    val canonicalIds = remember(canonicalItems) { canonicalItems.map { it.id } }
    val itemsById = remember(canonicalItems) { canonicalItems.associateBy { it.id } }
    val groupsById = remember(checklist.groups) { checklist.groups.associateBy { it.id } }
    val reorderDraft = remember(checklist.id) { IdReorderDraft(canonicalIds) }
    val visualItems = remember(reorderDraft.order, itemsById) { reorderDraft.order.mapNotNull(itemsById::get) }
    var dragOffsetY by remember(checklist.id) { mutableFloatStateOf(0f) }
    val edgeSize = with(LocalDensity.current) { 64.dp.toPx() }
    val edgeStep = with(LocalDensity.current) { 14.dp.toPx() }

    LaunchedEffect(canonicalIds, reorderDraft.draggingId) { reorderDraft.sync(canonicalIds) }

    fun reorderAtPointer() {
        val id = reorderDraft.draggingId ?: return
        val layout = listState.layoutInfo
        val held = layout.visibleItemsInfo.firstOrNull { it.key == id } ?: return
        val from = reorderDraft.order.indexOf(id)
        if (from < 0 || held.index != from) return // Wait for the preceding layout move.
        val center = held.offset + held.size / 2f + dragOffsetY
        val direction = if (center > held.offset + held.size / 2f) 1 else -1
        val targetIndex = from + direction
        val targetId = reorderDraft.order.getOrNull(targetIndex) ?: return
        val target = layout.visibleItemsInfo.firstOrNull { it.key == targetId } ?: return
        val crossed = if (direction > 0) center > target.offset + target.size / 2f
            else center < target.offset + target.size / 2f
        if (crossed && reorderDraft.moveTo(targetIndex)) {
            dragOffsetY += DragMotion.compensation(held.offset, held.size, target.offset, target.size, direction > 0)
        }
    }

    fun finishDrag(commit: Boolean) {
        val ids = reorderDraft.finish(commit)
        if (ids != null && !onReorder(ids)) {
            reorderDraft.sync(canonicalIds)
            Toast.makeText(context, "순서를 저장하지 못했습니다. 다시 시도해주세요.", Toast.LENGTH_LONG).show()
        }
        dragOffsetY = 0f
    }

    LaunchedEffect(reorderDraft.draggingId) {
        var previous = 0L
        while (reorderDraft.draggingId != null) {
            val frame = withFrameNanos { it }
            val scale = DragMotion.frameScale(previous, frame)
            previous = frame
            val layout = listState.layoutInfo
            val held = layout.visibleItemsInfo.firstOrNull { it.key == reorderDraft.draggingId }
            if (held != null) {
                val center = held.offset + held.size / 2f + dragOffsetY
                val top = layout.viewportStartOffset + edgeSize
                val bottom = layout.viewportEndOffset - edgeSize
                val speed = when {
                    center < top -> -edgeStep * ((top - center) / edgeSize).coerceIn(0f, 1f)
                    center > bottom -> edgeStep * ((center - bottom) / edgeSize).coerceIn(0f, 1f)
                    else -> 0f
                }
                if (speed != 0f) dragOffsetY += listState.scrollBy(speed * scale)
                reorderAtPointer()
            }
        }
    }

    BackHandler {
        when {
            assignmentGroupId != null || assignmentUngroup -> {
                assignmentGroupId = null
                assignmentUngroup = false
                selectedIdList = emptyList()
            }
            else -> onBack()
        }
    }

    val assignmentMode = assignmentGroupId != null || assignmentUngroup
    val assignmentGroup = checklist.groups.firstOrNull { it.id == assignmentGroupId }

    Scaffold(
        topBar = {
            ArmyristTopBar(
                title = checklist.title,
                subtitle = "CHECKLIST · 항목 ${checklist.items.size} · AUTO SAVE",
                leadingLabel = "홈",
                leadingIcon = ArmyristTopBarLeadingIcon.HOME,
                onLeading = onHome,
                secondaryLeadingLabel = "메뉴",
                onSecondaryLeading = onBack,
                onTitleClick = { titleEdit = true },
                actions = {
                    Box {
                        TextButton(onClick = { headerMenuOpen = true }) {
                            Text("⋮", color = ArmyristColors.OnDark, style = MaterialTheme.typography.titleLarge)
                        }
                        DropdownMenu(expanded = headerMenuOpen, onDismissRequest = { headerMenuOpen = false }) {
                            DropdownMenuItem(text = { Text("결과 전달") }, onClick = { headerMenuOpen = false; onResult() })
                            DropdownMenuItem(
                                text = { Text("알람음 일괄") },
                                onClick = {
                                    headerMenuOpen = false
                                    val enabledItems = checklist.items.filter { it.notificationEnabled }
                                    if (enabledItems.isNotEmpty()) {
                                        onPickNotificationSound(enabledItems.firstOrNull()?.notificationSoundUri) { soundUri ->
                                            onBulkNotificationSound(soundUri)
                                        }
                                    }
                                }
                            )
                            DropdownMenuItem(text = { Text("메모") }, onClick = { headerMenuOpen = false; memoEdit = true })
                            DropdownMenuItem(text = { Text("초기화") }, onClick = { headerMenuOpen = false; resetConfirm = true })
                            if (checklist.deletedItems.isNotEmpty()) {
                                DropdownMenuItem(
                                    text = { Text("삭제된 항목 ${checklist.deletedItems.size}") },
                                    onClick = { headerMenuOpen = false; trashOpen = true }
                                )
                            }
                        }
                    }
                }
            )
        }
    ) { padding ->
        Column(Modifier.fillMaxSize().padding(padding)) {
            if (!assignmentMode) {
                Row(
                    Modifier.fillMaxWidth().padding(horizontal = 8.dp, vertical = 5.dp),
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    ChecklistUtilityButton(text = "그룹 설정", onClick = { groupManager = true }, modifier = Modifier.weight(1f))
                    ChecklistUtilityButton(text = "그룹 지정", onClick = { groupPicker = true }, modifier = Modifier.weight(1f))
                    Box(Modifier.weight(1f)) {
                        OfflineVoiceButton(
                            toolContext = VoiceToolContext.CHECKLIST,
                            modifier = Modifier.fillMaxWidth(),
                            onTranscript = { transcript -> voiceDrafts = KoreanVoiceStructurer.checklist(transcript) },
                            onMessage = { voiceMessage = it }
                        )
                    }
                }
            }

            ChecklistProgressSummary(checklist)

            if (!assignmentMode) {
                Row(
                    Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 2.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (checklist.deletedItems.isNotEmpty()) {
                        TextButton(onClick = { trashOpen = true }) {
                            Text("삭제된 항목 ${checklist.deletedItems.size}")
                        }
                    }
                    Spacer(Modifier.weight(1f))
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        val detailSelected =
                            viewMode == ChecklistViewMode.DETAIL
                        val compactSelected =
                            viewMode == ChecklistViewMode.COMPACT

                        OutlinedButton(
                            onClick = {
                                viewMode = ChecklistViewMode.DETAIL
                            },
                            shape = ArmyristPanelShape,
                            border = BorderStroke(
                                1.dp,
                                if (detailSelected) {
                                    ArmyristColors.PrimaryControl
                                } else {
                                    ArmyristColors.Border
                                }
                            ),
                            colors = ButtonDefaults.outlinedButtonColors(
                                containerColor =
                                    if (detailSelected) {
                                        ArmyristColors.SecondaryControl
                                    } else {
                                        ArmyristColors.WorkSurface
                                    },
                                contentColor = ArmyristColors.PrimaryText
                            ),
                            contentPadding = PaddingValues(
                                horizontal = 12.dp,
                                vertical = 6.dp
                            )
                        ) {
                            Text("자세히")
                        }

                        OutlinedButton(
                            onClick = {
                                viewMode = ChecklistViewMode.COMPACT
                            },
                            shape = ArmyristPanelShape,
                            border = BorderStroke(
                                1.dp,
                                if (compactSelected) {
                                    ArmyristColors.PrimaryControl
                                } else {
                                    ArmyristColors.Border
                                }
                            ),
                            colors = ButtonDefaults.outlinedButtonColors(
                                containerColor =
                                    if (compactSelected) {
                                        ArmyristColors.SecondaryControl
                                    } else {
                                        ArmyristColors.WorkSurface
                                    },
                                contentColor = ArmyristColors.PrimaryText
                            ),
                            contentPadding = PaddingValues(
                                horizontal = 12.dp,
                                vertical = 6.dp
                            )
                        ) {
                            Text("간략히")
                        }
                    }
                }
            } else {
                Surface(
                    color = assignmentGroup?.let {
                        parseColor(it.color).copy(alpha = 0.14f)
                    } ?: ArmyristColors.SecondaryControl,
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Row(
                        Modifier.fillMaxWidth().padding(12.dp, 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(Modifier.weight(1f)) {
                            Text(
                                if (assignmentUngroup) "미지정으로 변경" else "${assignmentGroup?.name ?: "그룹"} 지정 중",
                                fontWeight = FontWeight.Bold
                            )
                            Text(
                                "항목을 터치해 선택 · ${selectedIds.size}개",
                                style = MaterialTheme.typography.bodySmall
                            )
                        }
                        TextButton(onClick = {
                            assignmentGroupId = null
                            assignmentUngroup = false
                            selectedIdList = emptyList()
                        }) { Text("취소") }
                        Button(
                            enabled = selectedIds.isNotEmpty(),
                            onClick = {
                                onAssignGroup(
                                    selectedIds,
                                    if (assignmentUngroup) null else assignmentGroupId
                                )
                                assignmentGroupId = null
                                assignmentUngroup = false
                                selectedIdList = emptyList()
                            }
                        ) { Text("확인") }
                    }
                }
            }

            HorizontalDivider()

            LazyColumn(
                state = listState,
                modifier = Modifier.fillMaxSize(),
                contentPadding = PaddingValues(8.dp, 6.dp, 8.dp, 24.dp),
                verticalArrangement = Arrangement.spacedBy(
                    if (viewMode == ChecklistViewMode.COMPACT) 4.dp else 7.dp
                )
            ) {
                itemsIndexed(
                    visualItems,
                    key = { _, item -> item.id },
                    contentType = { _, _ -> "checklist-item" }
                ) { index, item ->
                    val group = groupsById[item.groupId]
                    val selected = item.id in selectedIds

                    val dragging = reorderDraft.draggingId == item.id

                    val cardColor = when {
                        selected -> assignmentGroup?.let {
                            parseColor(it.color).copy(alpha = 0.26f)
                        } ?: ArmyristColors.SecondaryControl
                        group != null -> parseColor(group.color).copy(alpha = 0.13f)
                        else -> ArmyristColors.RaisedSurface
                    }

                    Card(
                        colors = CardDefaults.cardColors(containerColor = cardColor),
                        shape = ArmyristPanelShape,
                        border = BorderStroke(
                            1.dp,
                            group?.let { parseColor(it.color).copy(alpha = 0.72f) }
                                ?: ArmyristColors.Divider
                        ),
                        modifier = Modifier
                            .fillMaxWidth()
                            .zIndex(if (dragging) 1f else 0f)
                            .animateItem(fadeInSpec = null, fadeOutSpec = null,
                                placementSpec = if (dragging) null else spring(stiffness = Spring.StiffnessMediumLow, dampingRatio = Spring.DampingRatioNoBouncy))
                            .graphicsLayer { translationY = if (dragging) dragOffsetY else 0f }
                            .pointerInput(item.id, assignmentMode) {
                                if (!assignmentMode) {
                                    detectDragGesturesAfterLongPress(
                                        onDragStart = {
                                            if (reorderDraft.begin(item.id)) {
                                                dragOffsetY = 0f
                                                haptic.performHapticFeedback(HapticFeedbackType.LongPress)
                                            }
                                        },
                                        onDragCancel = { finishDrag(commit = false) },
                                        onDragEnd = { finishDrag(commit = true) },
                                        onDrag = { change, amount ->
                                            if (reorderDraft.draggingId == item.id) {
                                                change.consume()
                                                dragOffsetY += amount.y
                                                reorderAtPointer()
                                            }
                                        }
                                    )
                                }
                            }
                            .clickable {
                                if (assignmentMode) {
                                    selectedIdList =
                                        (if (selected) selectedIds - item.id
                                        else selectedIds + item.id).toList()
                                } else if (!dragging) {
                                    editingItem = item
                                }
                            }
                    ) {
                        if (viewMode == ChecklistViewMode.COMPACT && !assignmentMode) {
                            CompactChecklistRow(
                                index = index,
                                item = item,
                                groupName = group?.name ?: "미지정",
                                onStatus = { onStatus(item.id, it) }
                            )
                        } else {
                            DetailChecklistRow(
                                index = index,
                                item = item,
                                groupName = group?.name ?: "미지정",
                                selected = selected,
                                assignmentMode = assignmentMode,
                                onStatus = { onStatus(item.id, it) },
                                onEdit = { editingItem = item },
                                onDelete = { deleteTarget = item }
                            )
                        }
                    }
                }

                item {
                    OutlinedButton(
                        onClick = { addingItem = true },
                        modifier = Modifier.fillMaxWidth().heightIn(min = 52.dp),
                        shape = ArmyristPanelShape,
                        border = BorderStroke(1.dp, ArmyristColors.PrimaryControl)
                    ) { Text("+ 새 항목 추가") }
                }

                item {
                    Card(
                        onClick = { memoEdit = true },
                        modifier = Modifier.fillMaxWidth(),
                        shape = ArmyristPanelShape,
                        colors = CardDefaults.cardColors(
                            containerColor = ArmyristColors.RaisedSurface
                        ),
                        border = BorderStroke(1.dp, ArmyristColors.Border)
                    ) {
                        Column(Modifier.padding(14.dp)) {
                            Row(Modifier.fillMaxWidth()) {
                                Text("메모", fontWeight = FontWeight.Bold, modifier = Modifier.weight(1f))
                                Text("편집", color = ArmyristColors.PrimaryControl)
                            }
                            Spacer(Modifier.height(4.dp))
                            Text(
                                checklist.memo.ifBlank { "메모가 없습니다. 눌러서 입력하세요." },
                                color = if (checklist.memo.isBlank())
                                    MaterialTheme.colorScheme.onSurfaceVariant
                                else MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }
                }
            }
        }
    }

    if (titleEdit) {
        TextEditDialog("제목 변경", checklist.title, onDismiss = { titleEdit = false }) {
            if (it.trim().isNotEmpty()) onRename(it)
            titleEdit = false
        }
    }

    if (addingItem) {
        ItemEditDialog(
            item = null,
            groups = checklist.groups,
            onPickNotificationSound = onPickNotificationSound,
            onDismiss = { addingItem = false }
        ) {
                name, note, groupId, notificationEnabled, scheduledTimeMinutes, notificationSoundUri ->
            onAddItem(
                name,
                note,
                groupId,
                notificationEnabled,
                scheduledTimeMinutes,
                notificationSoundUri
            )
            addingItem = false
        }
    }

    editingItem?.let { item ->
        ItemEditDialog(
            item = item,
            groups = checklist.groups,
            onPickNotificationSound = onPickNotificationSound,
            onDismiss = { editingItem = null }
        ) {
                name, note, groupId, notificationEnabled, scheduledTimeMinutes, notificationSoundUri ->
            onEditItem(
                item.id,
                name,
                note,
                groupId,
                notificationEnabled,
                scheduledTimeMinutes,
                notificationSoundUri
            )
            editingItem = null
        }
    }

    if (memoEdit) {
        TextEditDialog("전체 메모", checklist.memo, true, { memoEdit = false }) {
            onMemo(it)
            memoEdit = false
        }
    }

    if (groupManager) {
        GroupManagerDialog(
            checklist = checklist,
            onAdd = onAddGroup,
            onColor = onGroupColor,
            onDelete = onDeleteGroup,
            onDismiss = { groupManager = false }
        )
    }

    if (groupPicker) {
        GroupPickerDialog(
            checklist = checklist,
            onDismiss = { groupPicker = false },
            onSelect = { groupId, ungroup ->
                groupPicker = false
                assignmentGroupId = groupId
                assignmentUngroup = ungroup
                selectedIdList = emptyList()
            }
        )
    }

    if (resetConfirm) {
        AlertDialog(
            onDismissRequest = { resetConfirm = false },
            title = { Text("상태 초기화") },
            text = { Text("모든 항목을 미완료로 되돌립니다. 항목·그룹·비고·메모는 유지됩니다.") },
            confirmButton = {
                TextButton(onClick = {
                    onReset()
                    resetConfirm = false
                }) { Text("초기화") }
            },
            dismissButton = {
                TextButton(onClick = { resetConfirm = false }) { Text("취소") }
            }
        )
    }

    deleteTarget?.let { item ->
        AlertDialog(
            onDismissRequest = { deleteTarget = null },
            title = { Text("항목 삭제") },
            text = {
                Text("'${item.name}'을 삭제된 항목으로 이동합니다. 나중에 복구할 수 있습니다.")
            },
            confirmButton = {
                TextButton(onClick = {
                    onDeleteItem(item.id)
                    deleteTarget = null
                }) { Text("삭제") }
            },
            dismissButton = {
                TextButton(onClick = { deleteTarget = null }) { Text("취소") }
            }
        )
    }

    if (trashOpen) {
        DeletedItemsDialog(
            checklist = checklist,
            onRestore = onRestoreItem,
            onRequestPermanentDelete = { permanentDeleteTarget = it },
            onDismiss = { trashOpen = false }
        )
    }

    permanentDeleteTarget?.let { item ->
        AlertDialog(
            onDismissRequest = { permanentDeleteTarget = null },
            title = { Text("영구 삭제") },
            text = {
                Text("'${item.name}'을 완전히 삭제합니다. 이 작업은 복구할 수 없습니다.")
            },
            confirmButton = {
                TextButton(onClick = {
                    onPermanentlyDeleteItem(item.id)
                    permanentDeleteTarget = null
                }) { Text("영구 삭제") }
            },
            dismissButton = {
                TextButton(onClick = { permanentDeleteTarget = null }) { Text("취소") }
            }
        )
    }

    voiceDrafts?.let { drafts ->
        ChecklistVoiceReviewDialog(
            initial = drafts,
            onDismiss = { voiceDrafts = null },
            onApply = { applied ->
                applied.forEach { d ->
                    onAddItem(
                        d.name,
                        d.note,
                        null,
                        false,
                        d.scheduledTimeMinutes,
                        null
                    )
                }
                voiceDrafts = null
            }
        )
    }

    voiceMessage?.let { msg ->
        AlertDialog(
            onDismissRequest = { voiceMessage = null },
            title = { Text("음성 입력") },
            text = { Text(msg) },
            confirmButton = { TextButton(onClick = { voiceMessage = null }) { Text("확인") } }
        )
    }
}

