    if (exporting) PortableWorkDialog()

    suspend fun createPortableBytes(): ByteArray? {
        val type = portableType
        val rootId = portableRootId
        if (type == null || rootId.isNullOrBlank()) {
            Toast.makeText(
                context,
                "이 화면에서는 데이터 파일을 만들 수 없습니다.",
                Toast.LENGTH_SHORT
            ).show()
            return null
        }

        if (
            encrypt &&
            (
                password.isBlank() ||
                password != passwordConfirm
            )
        ) {
            Toast.makeText(
                context,
                "암호와 암호 확인을 동일하게 입력해주세요.",
                Toast.LENGTH_SHORT
            ).show()
            return null
        }

        val chars = if (encrypt) password.toCharArray() else null
        val generated = withContext(Dispatchers.Default) {
            try {
                ArmyristPortableDataManager.createIndividualExport(context, type, rootId, chars)
            } finally { chars?.fill('\u0000') }
        }
        return when (generated) {
            is PortableResult.Success -> generated.value
            is PortableResult.Error -> {
                Toast.makeText(
                    context,
                    generated.message,
                    Toast.LENGTH_LONG
                ).show()
                null
            }
        }
    }

    fun exportPortable(onReady: (ByteArray) -> Unit) {
        if (exporting) return
        exporting = true
        scope.launch {
            try { createPortableBytes()?.let(onReady) }
            finally { exporting = false }
        }
    }

    fun fileName(): String {
        val type = when (portableType) {
            ArmyristPortableDataType.COUNTING -> "counting"
            ArmyristPortableDataType.CHECKLIST -> "checklist"
            ArmyristPortableDataType.TIME_PLAN -> "time-plan"
            ArmyristPortableDataType.REPORT_TEMPLATE -> "report-template"
            else -> "armyrist-data"
        }
        return "$type-${System.currentTimeMillis()}.armyrist"
    }

    fun sharePortable(bytes: ByteArray) {
        runCatching {
            val directory =
                File(context.cacheDir, "portable-share").apply {
                    mkdirs()
                }
            directory.listFiles()?.forEach {
