class DataManagementActivity : ComponentActivity() {
    private var backupBusy by mutableStateOf(false)
    private var pendingBackupBytes: ByteArray? = null
    private var selectedRestoreBytes: ByteArray? = null

    private val createBackupFile =
        registerForActivityResult(
            ActivityResultContracts.CreateDocument(
                "application/octet-stream"
            )
        ) { uri ->
            val bytes = pendingBackupBytes
            pendingBackupBytes = null

            if (uri != null && bytes != null) {
                runCatching {
                    contentResolver.openOutputStream(uri)?.use {
                        it.write(bytes)
                    } ?: error("openOutputStream failed")
                }.onSuccess {
                    Toast.makeText(
                        this,
                        "백업 파일을 저장했습니다.",
                        Toast.LENGTH_SHORT
                    ).show()
                }.onFailure {
                    Toast.makeText(
                        this,
                        "백업 파일을 저장할 수 없습니다.",
                        Toast.LENGTH_SHORT
                    ).show()
                }
            }
        }

    private val openRestoreFile =
        registerForActivityResult(
            ActivityResultContracts.OpenDocument()
        ) { uri ->
            if (uri != null) {
                selectedRestoreBytes =
                    readUriBytesSafely(uri)

                selectedRestoreBytes?.let {
                    onRestoreFileSelected?.invoke(it)
                }
            }
        }

    private var onRestoreFileSelected:
        ((ByteArray) -> Unit)? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        ArmyristPortableDataManager
            .recoverInterruptedRestore(this)

        setContent {
            ArmyristTheme {
                Surface(
                    Modifier.fillMaxSize(),
                    color = ArmyristColors.AppBackground
                ) {
                    DataManagementScreen(
                        onBack = { finish() },
                        backupBusy = backupBusy,
                        onCreateBackup = { encrypted, password ->
                            if (!backupBusy) {
                                backupBusy = true
                                lifecycleScope.launch {
                                    try {
                                        val chars = if (encrypted) password.toCharArray() else null
                                        val result = withContext(Dispatchers.Default) {
                                            try {
                                                ArmyristPortableDataManager.createFullBackup(this@DataManagementActivity, chars)
                                            } finally { chars?.fill('\u0000') }
                                        }
                                        when (result) {
                                            is PortableResult.Success -> {
                                                pendingBackupBytes = result.value
                                                createBackupFile.launch("armyrist-backup-${LocalDate.now()}.armyrist")
                                            }
                                            is PortableResult.Error -> Toast.makeText(
                                                this@DataManagementActivity, result.message, Toast.LENGTH_LONG
                                            ).show()
                                        }
                                    } finally { backupBusy = false }
                                }
                            }
                        },
                        onChooseRestoreFile = { callback ->
                            onRestoreFileSelected = callback
                            openRestoreFile.launch(
                                arrayOf(
                                    "application/octet-stream",
                                    "application/json",
                                    "*/*"
                                )
                            )
                        },
                        onRestoreValidated = { backup ->
                            when (
                                ArmyristPortableDataManager
                                    .restoreFullBackup(
                                        this,
                                        backup
                                    )
                            ) {
                                is PortableResult.Success -> {
                                    (application as ArmyristApplication)
                                        .reloadAfterPortableDataChange()
                                    Toast.makeText(
                                        this,
                                        "전체 복원이 완료되었습니다.",
                                        Toast.LENGTH_SHORT
                                    ).show()
                                    true
                                }
                                is PortableResult.Error -> false
                            }
                        }
                    )
                }
            }
        }
    }

    private fun readUriBytesSafely(uri: Uri): ByteArray? {
        return runCatching {
            contentResolver.openInputStream(uri)?.use { stream ->
                val maxBytes = 32 * 1024 * 1024
                val buffer = ByteArray(8192)
                val output = java.io.ByteArrayOutputStream()
                var total = 0

                while (true) {
                    val count = stream.read(buffer)
                    if (count < 0) break
                    total += count
                    require(total <= maxBytes)
                    output.write(buffer, 0, count)
                }
                output.toByteArray()
            } ?: error("openInputStream failed")
        }.getOrElse {
            Toast.makeText(
                this,
                "파일이 너무 크거나 읽을 수 없습니다.",
                Toast.LENGTH_SHORT
            ).show()
            null
        }
    }
}

