                    "복원 실패 시 기존 데이터는 유지됩니다.",
                    style = MaterialTheme.typography.bodySmall,
                    color = ArmyristColors.SecondaryText
                )
                Spacer(Modifier.height(12.dp))
                ArmyristActionButton(
                    text = "백업 파일 선택",
                    onClick = {
                        onChooseRestoreFile { bytes ->
                            restoreBytes = bytes
                            when (
                                val inspection =
                                    ArmyristPortableDataManager
                                        .inspect(bytes)
                            ) {
                                is PortableResult.Success -> {
                                    restoreInspection =
                                        inspection.value
                                    if (inspection.value.encrypted) {
                                        restorePasswordDialog = true
                                    } else {
                                        validateRestore(bytes, null)
                                    }
                                }
                                is PortableResult.Error -> {
                                    Toast.makeText(
                                        context,
                                        inspection.message,
                                        Toast.LENGTH_SHORT
                                    ).show()
                                }
                            }
                        }
                    },
                    modifier = Modifier.fillMaxWidth()
                )
            }

            ArmyristPanel(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    "개별 데이터 가져오기",
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(8.dp))
                Text("실셈·체크리스트·시간계획·보고 양식 .armyrist 파일을 새 문서로 추가합니다.")
                Spacer(Modifier.height(12.dp))
                ArmyristActionButton(
                    text = "데이터 가져오기",
                    onClick = {
                        context.startActivity(
                            android.content.Intent(
                                context,
                                PortableTransferActivity::class.java
                            ).apply {
                                putExtra(
                                    PortableTransferActivity.EXTRA_MODE,
                                    PortableTransferActivity.MODE_IMPORT
                                )
                            }
                        )
                    },
                    modifier = Modifier.fillMaxWidth()
                )

                Spacer(Modifier.height(8.dp))
                ArmyristActionButton(
                    text = "주변 Armyrist 수신 (PoC)",
                    onClick = {
                        context.startActivity(
                            android.content.Intent(context, NearbyTransferActivity::class.java)
                        )
                    },
                    modifier = Modifier.fillMaxWidth(),
                    primary = false
                )
            }
        }
    }

    if (passwordDialog) {
        PasswordConfirmDialog(
            title = "백업 파일 암호화",
            onDismiss = { passwordDialog = false },
            onConfirm = { password ->
                passwordDialog = false
                onCreateBackup(true, password)
            }
        )
    }

    if (restorePasswordDialog) {
        PasswordInputDialog(
            title = "암호화된 Armyrist 파일",
            onDismiss = {
                restorePasswordDialog = false
                restoreBytes = null
            },
            onConfirm = { password ->
                val bytes = restoreBytes ?: return@PasswordInputDialog
                validateRestore(bytes, password)
            }
        )
    }

    if (restoreConfirm) {
        val backup = restoreBackup
        if (backup != null) {
            RestoreConfirmDialog(
                backup = backup,
                current =
                    ArmyristPortableDataManager.currentSummary(
                        context
                    ),
                onDismiss = {
                    restoreConfirm = false
                    restoreBackup = null
                    restoreBytes = null
                },
                onConfirm = {
                    if (onRestoreValidated(backup)) {
                        restoreConfirm = false
                        restoreBackup = null
                        restoreBytes = null
                    }
                }
            )
        }
    }
}

