private enum class Screen { SHEETS, COUNTING, GROUPS, CALCULATIONS, RESULT }
private enum class CountingViewMode { DETAILED, COMPACT }

@Composable
private fun ArmyristApp(
    repo: CountingRepository,
    coreRepo: CoreSuiteRepository,
    trashRepo: CommonTrashRepository,
    onHome: () -> Unit
) {
    var screenName by rememberSaveable { mutableStateOf(Screen.SHEETS.name) }
    val screen = runCatching { Screen.valueOf(screenName) }.getOrDefault(Screen.SHEETS)
    var selectedSheetId by rememberSaveable { mutableStateOf<String?>(null) }
    var revision by remember { mutableIntStateOf(0) }
    @Suppress("UNUSED_VARIABLE")
    val observedRevision = revision

    fun refresh() {
        revision++
    }

    when (screen) {
        Screen.SHEETS -> SheetListScreen(
            sheets = repo.getSheets(),
            trashRepo = trashRepo,
            onHome = onHome,
            onCreate = {
                val created = repo.createSheet()
                if (created != null) {
                    selectedSheetId = created.id
                    refresh()
                    screenName = Screen.COUNTING.name
                }
            },
            onOpen = {
                selectedSheetId = it
                screenName = Screen.COUNTING.name
            },
            onRename = { id, title ->
                if (repo.renameSheet(id, title)) refresh()
            },
            onDeleteToTrash = { id ->
                val current = repo.getSheet(id)
                val payload = repo.exportSheetTrashPayload(id)
                if (current == null || payload == null) {
                    false
                } else {
                    val trashItem = trashRepo.moveToTrash(
                        toolType = TrashToolType.COUNTING,
                        originalId = current.id,
                        title = current.title,
                        payloadVersion = 1,
                        payload = payload
                    )
                    if (trashItem == null) {
                        false
                    } else if (repo.deleteSheetForTrash(id)) {
                        refresh()
                        true
                    } else {
                        trashRepo.permanentlyDelete(trashItem.id)
                        false
                    }
                }
            },
            onRestoreTrash = { item ->
                if (repo.restoreSheetTrashPayload(item.payload)) {
                    trashRepo.permanentlyDelete(item.id)
                    refresh()
                    true
                } else false
            },
            onPermanentDeleteTrash = { item ->
                val deleted = trashRepo.permanentlyDelete(item.id)
                if (deleted) refresh()
                deleted
            }
        )

        else -> {
            val id = selectedSheetId
            val sheet = id?.let(repo::getSheet)

            if (sheet == null) {
                screenName = Screen.SHEETS.name
            } else {
                when (screen) {
                    Screen.COUNTING -> CountingScreen(
                        sheet = sheet,
                        onHome = onHome,
                        onBack = { screenName = Screen.SHEETS.name },
                        onAddGroup = { name, color, showAggregate ->
                            if (
                                repo.addGroup(
                                    sheet.id,
                                    name,
                                    color,
                                    showAggregate
                                )
                            ) refresh()
                        },
                        onRenameGroup = {
                            groupId,
                            name,
                            color,
                            showAggregate ->
                            if (
                                repo.renameGroup(
                                    sheet.id,
                                    groupId,
                                    name,
                                    color,
                                    showAggregate
                                )
                            ) refresh()
                        },
                        onDeleteGroup = {
                            repo.deleteGroup(sheet.id, it)
                            refresh()
                        },
                        onCalculations = { screenName = Screen.CALCULATIONS.name },
                        onResult = { screenName = Screen.RESULT.name },
                        onRename = {
                            if (repo.renameSheet(sheet.id, it)) refresh()
                        },
                        onMemo = {
                            repo.setMemo(sheet.id, it)
                            refresh()
                        },
                        onAddItem = { name, quantity, unit, note, groupId ->
                            if (repo.addItem(sheet.id, name, quantity, unit, note, groupId)) refresh()
                        },
                        onEditItem = { itemId, name, unit, note, groupId ->
                            if (repo.editItem(sheet.id, itemId, name, unit, note, groupId)) refresh()
                        },
                        onDeleteItem = {
                            repo.deleteItem(sheet.id, it)
                            refresh()
                        },
                        onIncrement = {
                            repo.increment(sheet.id, it)
                            refresh()
                        },
                        onDecrement = {
                            repo.decrement(sheet.id, it)
                            refresh()
                        },
                        onQuantity = { itemId, quantity ->
                            if (repo.setQuantity(sheet.id, itemId, quantity)) refresh()
                        },
                        onMove = { itemId, delta ->
                            repo.moveItem(sheet.id, itemId, delta)
                            refresh()
                        },
                        onReorder = { orderedIds ->
                            val saved = repo.reorderItems(sheet.id, orderedIds)
                            if (saved) refresh()
                            saved
                        },
                        onAssignGroup = { itemIds, groupId ->
                            if (repo.assignItemsToGroup(sheet.id, itemIds, groupId)) refresh()
                        }
                    )

                    Screen.GROUPS -> GroupScreen(
                        sheet = sheet,
                        onBack = { screenName = Screen.COUNTING.name },
                        onAdd = { name, color, showAggregate ->
                            if (
                                repo.addGroup(
                                    sheet.id,
                                    name,
                                    color,
                                    showAggregate
                                )
                            ) refresh()
                        },
                        onRename = {
                            groupId,
                            name,
                            color,
                            showAggregate ->
                            if (
                                repo.renameGroup(
                                    sheet.id,
                                    groupId,
                                    name,
                                    color,
                                    showAggregate
                                )
                            ) refresh()
                        },
                        onDelete = {
                            repo.deleteGroup(sheet.id, it)
                            refresh()
                        }
                    )

                    Screen.CALCULATIONS -> CalculationScreen(
                        sheet = sheet,
                        onBack = { screenName = Screen.COUNTING.name },
                        onAdd = { left, operator, right, name ->
                            if (repo.addCalculation(sheet.id, left, operator, right, name)) refresh()
                        },
                        onEdit = { calcId, left, operator, right, name ->
                            if (repo.editCalculation(sheet.id, calcId, left, operator, right, name)) refresh()
                        },
                        onDelete = {
                            repo.deleteCalculation(sheet.id, it)
                            refresh()
                        }
                    )

                    Screen.RESULT -> CommonShareScreen(
                        repo = coreRepo,
                        result = ToolResult(
                            title = sheet.title,
                            body = ResultGenerator.generate(sheet)
                        ),
                        onBack = { screenName = Screen.COUNTING.name },
                        portableType = ArmyristPortableDataType.COUNTING,
                        portableRootId = sheet.id
                    )

                    Screen.SHEETS -> Unit
                }
            }
        }
    }
}

