internal enum class PortableLaunchRoute {
    INTERNAL_EXPORT,
    INTERNAL_IMPORT,
    EXTERNAL_VIEW,
    EXTERNAL_SEND,
    INVALID_EXTERNAL,
    UNSUPPORTED
}

internal fun resolvePortableLaunchRoute(
    action: String?,
    extraMode: String?,
    hasViewUri: Boolean,
    hasSendUri: Boolean
): PortableLaunchRoute = when (action) {
    "android.intent.action.VIEW" ->
        if (hasViewUri) PortableLaunchRoute.EXTERNAL_VIEW
        else PortableLaunchRoute.INVALID_EXTERNAL

    "android.intent.action.SEND" ->
        if (hasSendUri) PortableLaunchRoute.EXTERNAL_SEND
        else PortableLaunchRoute.INVALID_EXTERNAL

    else -> when (extraMode) {
        PortableTransferActivity.MODE_EXPORT ->
            PortableLaunchRoute.INTERNAL_EXPORT
        PortableTransferActivity.MODE_IMPORT ->
            PortableLaunchRoute.INTERNAL_IMPORT
        PortableTransferActivity.MODE_IMPORT_BYTES ->
            PortableLaunchRoute.INTERNAL_IMPORT
        else ->
            PortableLaunchRoute.UNSUPPORTED
    }
}

class PortableTransferActivity : ComponentActivity() {
    companion object {
        const val EXTRA_MODE = "mode"
        const val EXTRA_TYPE = "type"
        const val EXTRA_ROOT_ID = "rootId"
        const val MODE_EXPORT = "export"
        const val MODE_IMPORT = "import"
        const val MODE_IMPORT_BYTES = "importBytes"
        const val EXTRA_CACHE_FILE = "cacheFile"
        const val ARMYRIST_MIME = "application/vnd.armyrist.data"
    }

    private var pendingBytes: ByteArray? = null
    private var importBytes: ByteArray? = null

    private val createFile = registerForActivityResult(
        ActivityResultContracts.CreateDocument(ARMYRIST_MIME)
    ) { uri ->
        val bytes = pendingBytes
        pendingBytes = null
        if (uri != null && bytes != null) {
            runCatching {
                contentResolver.openOutputStream(uri)?.use { it.write(bytes) }
                    ?: error("open failed")
            }.onSuccess {
                Toast.makeText(this, "아미리스 데이터 파일을 저장했습니다.", Toast.LENGTH_SHORT).show()
            }.onFailure {
                Toast.makeText(this, "파일을 저장할 수 없습니다.", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private val openFile = registerForActivityResult(
        ActivityResultContracts.OpenDocument()
    ) { uri ->
        if (uri == null) return@registerForActivityResult
        val bytes = readUriBytesSafely(uri)
            ?: return@registerForActivityResult
        importBytes = bytes
        renderImport(bytes)
    }

    private fun readUriBytesSafely(
        uri: android.net.Uri
    ): ByteArray? {
        return runCatching {
            contentResolver.openInputStream(uri)?.use { stream ->
                val maxBytes = 32 * 1024 * 1024
                val buffer = ByteArray(8192)
                val output = java.io.ByteArrayOutputStream()
                var total = 0

                while (true) {
                    val count = stream.read(buffer)
                    if (count < 0) break
                    total += count
                    require(total <= maxBytes)
                    output.write(buffer, 0, count)
                }
                output.toByteArray()
            } ?: error("openInputStream failed")
        }.getOrElse {
            Toast.makeText(
                this,
                "파일이 너무 크거나 읽을 수 없습니다.",
                Toast.LENGTH_SHORT
            ).show()
            null
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        val viewUri =
            if (intent.action == Intent.ACTION_VIEW) intent.data else null

        val sendUri =
            if (intent.action == Intent.ACTION_SEND) {
                if (android.os.Build.VERSION.SDK_INT >= 33) {
                    intent.getParcelableExtra(
                        Intent.EXTRA_STREAM,
                        android.net.Uri::class.java
                    )
                } else {
                    @Suppress("DEPRECATION")
                    intent.getParcelableExtra(Intent.EXTRA_STREAM)
                }
            } else {
                null
            }

        if (intent.getStringExtra(EXTRA_MODE) == MODE_IMPORT_BYTES) {
            val path = intent.getStringExtra(EXTRA_CACHE_FILE)
            val file = path?.let(::File)
            if (file == null || !file.exists() || !file.canonicalPath.startsWith(cacheDir.canonicalPath)) {
                Toast.makeText(this, "수신 데이터를 읽을 수 없습니다.", Toast.LENGTH_LONG).show()
                finish()
                return
            }
            val bytes = runCatching { file.readBytes() }.getOrNull()
            file.delete()
            if (bytes == null) {
                finish()
                return
            }
            importBytes = bytes
            renderImport(bytes)
            return
        }

        when (
            resolvePortableLaunchRoute(
                action = intent.action,
                extraMode = intent.getStringExtra(EXTRA_MODE),
                hasViewUri = viewUri != null,
                hasSendUri = sendUri != null
            )
        ) {
            PortableLaunchRoute.INTERNAL_EXPORT ->
                renderExport()

            PortableLaunchRoute.INTERNAL_IMPORT ->
                openFile.launch(
                    arrayOf(
                        ARMYRIST_MIME,
                        "application/octet-stream",
                        "application/json",
                        "*/*"
                    )
                )

            PortableLaunchRoute.EXTERNAL_VIEW ->
                startExternalImport(viewUri!!)

            PortableLaunchRoute.EXTERNAL_SEND ->
                startExternalImport(sendUri!!)

            PortableLaunchRoute.INVALID_EXTERNAL -> {
                Toast.makeText(
                    this,
                    "전달된 Armyrist 데이터 파일을 찾을 수 없습니다.",
                    Toast.LENGTH_LONG
                ).show()
                finish()
            }

            PortableLaunchRoute.UNSUPPORTED ->
                finish()
        }
    }

    private fun startExternalImport(uri: android.net.Uri) {
        val bytes = readUriBytesSafely(uri)

        if (bytes == null) {
            finish()
            return
        }

        importBytes = bytes
        renderImport(bytes)
    }

    private fun shareArmyristFile(
        bytes: ByteArray,
        filename: String
    ) {
        runCatching {
            val directory = File(
                cacheDir,
                "portable-share"
            ).apply {
                mkdirs()
            }

            directory.listFiles()?.forEach { file ->
                if (file.isFile) file.delete()
            }

            val file = File(directory, filename)
            file.writeBytes(bytes)

            val uri = FileProvider.getUriForFile(
                this,
                "$packageName.fileprovider",
                file
            )

            val sendIntent = Intent(Intent.ACTION_SEND).apply {
                type = ARMYRIST_MIME
                putExtra(Intent.EXTRA_STREAM, uri)
                addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            }

            startActivity(
                Intent.createChooser(
                    sendIntent,
                    "아미리스 데이터 공유"
                )
            )
        }.onFailure {
            Toast.makeText(
                this,
                "데이터 파일을 공유할 수 없습니다.",
                Toast.LENGTH_SHORT
            ).show()
        }
    }

