    private fun renderImport(bytes: ByteArray) {
        val inspection = ArmyristPortableDataManager.inspect(bytes)
        if (inspection is PortableResult.Error) {
            Toast.makeText(this, inspection.message, Toast.LENGTH_LONG).show()
            finish()
            return
        }
        inspection as PortableResult.Success
        if (inspection.value.dataType == ArmyristPortableDataType.BACKUP) {
            Toast.makeText(this, "전체 백업 파일은 데이터 관리의 전체 복원을 사용해주세요.", Toast.LENGTH_LONG).show()
            finish()
            return
        }

        setContent {
            ArmyristTheme {
                var password by remember { mutableStateOf("") }
                var validated by remember {
                    mutableStateOf<ArmyristPortableDataManager.ValidatedPortableDocument?>(null)
                }
                var legacyBaseDate by remember { mutableStateOf(LocalDate.now()) }
                var legacyDatePickerOpen by remember { mutableStateOf(false) }
                val encrypted = inspection.value.encrypted

                val scope = rememberCoroutineScope()
                var validating by remember { mutableStateOf(false) }
                if (validating) PortableWorkDialog()

                fun validateNow() {
                    if (validating) return
                    validating = true
                    val chars = if (encrypted) password.toCharArray() else null
                    scope.launch {
                        try {
                            val result = withContext(Dispatchers.Default) {
                                try { ArmyristPortableDataManager.validateIndividualImport(bytes, chars) }
                                finally { chars?.fill('\u0000') }
                            }
                            when (result) {
                                is PortableResult.Success -> validated = result.value
                                is PortableResult.Error -> Toast.makeText(
                                    this@PortableTransferActivity, result.message, Toast.LENGTH_LONG
                                ).show()
                            }
                        } finally { validating = false }
                    }
                }

                LaunchedEffect(Unit) {
                    if (!encrypted) validateNow()
                }

                Scaffold(
                    topBar = {
                        ArmyristTopBar(
                            title = "데이터 가져오기",
                            subtitle = "${typeLabel(inspection.value.dataType)} · 새 문서 생성",
                            leadingLabel = "취소",
                            onLeading = { finish() }
                        )
                    }
                ) { padding ->
                    Column(
                        Modifier.fillMaxSize().padding(padding).padding(16.dp),
                        verticalArrangement = Arrangement.spacedBy(14.dp)
                    ) {
                        if (encrypted && validated == null) {
                            ArmyristPanel(Modifier.fillMaxWidth()) {
                                Text("암호화된 Armyrist 파일입니다.", fontWeight = FontWeight.Bold)
                                Spacer(Modifier.height(10.dp))
                                OutlinedTextField(
                                    value = password,
                                    onValueChange = { password = it },
                                    label = { Text("암호") },
                                    visualTransformation = PasswordVisualTransformation(),
                                    modifier = Modifier.fillMaxWidth()
                                )
                                Spacer(Modifier.height(10.dp))
                                Button(
                                    onClick = { validateNow() },
                                    modifier = Modifier.fillMaxWidth(),
                                    shape = ArmyristPanelShape
                                ) { Text("확인") }
                            }
                        }

                        validated?.let { data ->
                            val p = data.preview
                            ArmyristPanel(Modifier.fillMaxWidth()) {
                                Text(p.title, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)
                                Spacer(Modifier.height(8.dp))
                                Text("종류: ${typeLabel(p.dataType)}")
                                if (p.itemCount > 0) Text("항목: ${p.itemCount}개")
                                if (p.groupCount > 0) Text("그룹: ${p.groupCount}개")
                                if (p.calculationCount > 0) Text("계산: ${p.calculationCount}개")
                                if (p.scheduledCount > 0) Text("예정시각 설정: ${p.scheduledCount}개")
                                Spacer(Modifier.height(10.dp))
                                Text(
                                    "기존 문서는 변경하지 않고 새로운 문서로 추가됩니다.",
                                    color = ArmyristColors.SecondaryText
                                )
                                val isLegacyTimePlan =
                                    p.dataType == ArmyristPortableDataType.TIME_PLAN &&
                                        data.timePlanSchemaVersion != null &&
                                        data.timePlanSchemaVersion !in setOf(3, 4, 5)

                                if (isLegacyTimePlan) {
                                    Spacer(Modifier.height(8.dp))
                                    Text(
                                        "날짜 기능 이전 시간계획입니다. 기준 날짜를 지정하면 날짜 기반 시간계획으로 변환해 가져옵니다.",
                                        color = ArmyristColors.PrimaryControl,
                                        fontWeight = FontWeight.Bold
                                    )
                                    Spacer(Modifier.height(10.dp))
                                    Row(
                                        modifier = Modifier.fillMaxWidth(),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        OutlinedButton(onClick = {
                                            legacyBaseDate = legacyBaseDate.minusDays(1)
                                        }) { Text("-1일") }
                                        Text(
                                            legacyBaseDate.format(DateTimeFormatter.ISO_DATE),
                                            fontWeight = FontWeight.Bold
                                        )
                                        OutlinedButton(onClick = {
                                            legacyBaseDate = legacyBaseDate.plusDays(1)
                                        }) { Text("+1일") }
                                    }
                                    TextButton(
                                        onClick = { legacyDatePickerOpen = true },
                                        modifier = Modifier.fillMaxWidth()
                                    ) { Text("달력에서 선택") }
                                }
                                Spacer(Modifier.height(14.dp))
                                Button(
                                    onClick = {
                                        when (val result = ArmyristPortableDataManager.importIndividual(
                                            this@PortableTransferActivity,
                                            data,
                                            if (isLegacyTimePlan) legacyBaseDate else null
                                        )) {
                                            is PortableResult.Success -> {
                                                val app =
                                                    application as ArmyristApplication

                                                // importIndividual commits directly to the portable
                                                // SharedPreferences snapshots. Repository instances
                                                // cache domain lists in memory, so they must be reloaded
                                                // before returning to the tool list.
                                                app.reloadAfterPortableDataChange()

                                                Toast.makeText(
                                                    this@PortableTransferActivity,
                                                    "새 ${typeLabel(p.dataType)} 문서로 가져왔습니다.",
                                                    Toast.LENGTH_SHORT
                                                ).show()
                                                finish()
                                            }
                                            is PortableResult.Error -> Toast.makeText(
                                                this@PortableTransferActivity,
                                                result.message,
                                                Toast.LENGTH_LONG
                                            ).show()
                                        }
                                    },
                                    modifier = Modifier.fillMaxWidth().heightIn(min = 54.dp),
                                    shape = ArmyristPanelShape
                                ) { Text("가져오기", fontWeight = FontWeight.Bold) }
                            }

                            if (legacyDatePickerOpen) {
                                val datePickerState = rememberDatePickerState(
                                    initialSelectedDateMillis = legacyBaseDate
                                        .atStartOfDay(ZoneOffset.UTC)
                                        .toInstant()
                                        .toEpochMilli()
                                )
                                DatePickerDialog(
                                    onDismissRequest = { legacyDatePickerOpen = false },
                                    confirmButton = {
                                        TextButton(onClick = {
                                            datePickerState.selectedDateMillis?.let { millis ->
                                                legacyBaseDate = Instant.ofEpochMilli(millis)
                                                    .atZone(ZoneOffset.UTC)
                                                    .toLocalDate()
                                            }
                                            legacyDatePickerOpen = false
                                        }) { Text("확인") }
                                    },
                                    dismissButton = {
                                        TextButton(onClick = { legacyDatePickerOpen = false }) {
                                            Text("취소")
                                        }
                                    }
                                ) {
                                    DatePicker(state = datePickerState)
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private fun typeLabel(type: ArmyristPortableDataType): String = when (type) {
        ArmyristPortableDataType.BACKUP -> "전체 백업"
        ArmyristPortableDataType.COUNTING -> "실셈"
        ArmyristPortableDataType.CHECKLIST -> "체크리스트"
        ArmyristPortableDataType.TIME_PLAN -> "시간계획"
        ArmyristPortableDataType.REPORT_TEMPLATE -> "보고 양식"
    }

    private fun safeTypeName(type: ArmyristPortableDataType): String = when (type) {
        ArmyristPortableDataType.COUNTING -> "counting"
        ArmyristPortableDataType.CHECKLIST -> "checklist"
        ArmyristPortableDataType.TIME_PLAN -> "time-plan"
        ArmyristPortableDataType.REPORT_TEMPLATE -> "report-template"
        ArmyristPortableDataType.BACKUP -> "backup"
    }
}

package com.seolhwa.armyrist.counting.reorder

import androidx.compose.runtime.Stable
import androidx.compose.runtime.derivedStateOf
import androidx.compose.runtime.getValue
import androidx.compose.runtime.setValue
import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import com.seolhwa.armyrist.domain.CountingItem
import kotlin.math.abs

enum class CountingReorderMode { DETAILED, COMPACT }

data class CountingReorderSlot(
    val itemId: String,
    val index: Int,
    val centerX: Float,
    val centerY: Float,
    val width: Float,
    val height: Float
)

/**
 * Counting Reorder V5
 *
 * Reusable contract:
 * 1. Canonical repository order never changes during pointer movement.
 * 2. The dragged ID is removed from backgroundOrder.
 * 3. A single placeholderIndex represents the insertion location.
 * 4. UI projection inserts the dragged ID only for layout/placeholder sizing.
 * 5. Drop publishes exactly one final ID order.
 *
 * This avoids the ambiguous "move the dragged item through the list while it
 * is also being rendered as an overlay" state that caused asymmetric compact
 * movement and failed return-to-origin gestures.
 */
@Stable
class CountingReorderV2(
    initialItems: List<CountingItem>,
    private val nowMillis: () -> Long = { android.os.SystemClock.uptimeMillis() }
) {
    private val canonicalItems =
        mutableStateListOf<CountingItem>().apply {
            addAll(initialItems.sortedBy { it.order })
        }

    private val restingOrder =
        mutableStateListOf<String>().apply {
            addAll(canonicalItems.map { it.id })
        }

    private val backgroundOrder =
        mutableStateListOf<String>()

    private val _placeholderIndex = mutableStateOf(0)
    val placeholderIndex: Int
        get() = _placeholderIndex.value

    var draggingItemId: String? by mutableStateOf(null)
        private set

    var mode: CountingReorderMode? by mutableStateOf(null)
        private set

    private var dragStartOrder: List<String> = restingOrder.toList()
    private var pendingCommit: List<String>? = null
    private var lastPlaceholderMoveAtMs: Long = 0L

    // Detailed-mode direction memory.
    // The previous nearest-slot implementation could reverse itself after a
    // LazyColumn relayout even while the finger was still travelling upward.
    // Keep the user's actual pointer direction as the source of truth.
    private var lastDetailedPointerY: Float = Float.NaN
    private var detailedDirection: Int = 0
    private var detailedDragStartedAtMs: Long = 0L
    private var lastDetailedMoveAtMs: Long = 0L

    val isDragging: Boolean
        get() = draggingItemId != null

    private fun projectedIds(): List<String> {
        val dragged = draggingItemId ?: return restingOrder.toList()
        val result = backgroundOrder.toMutableList()
        val insertion =
            placeholderIndex.coerceIn(0, result.size)
        result.add(insertion, dragged)
        return result
    }

    /**
     * Projection keeps the dragged item in the Lazy layout only as an
     * invisible size-preserving placeholder. Its visible representation is
     * owned by the stable parent overlay.
     */
    private val canonicalById = derivedStateOf { canonicalItems.associateBy { it.id } }
    private val restingIndices = derivedStateOf { restingOrder.withIndex().associate { it.value to it.index } }
    private val backgroundIndices = derivedStateOf { backgroundOrder.withIndex().associate { it.value to it.index } }
    private val projectedItems = derivedStateOf {
        val byId = canonicalById.value
        projectedIds().mapNotNull(byId::get)
    }

    val items: List<CountingItem> get() = projectedItems.value

    /** O(1) lookup without allocating the entire projection on every pointer event. */
    fun projectedIndexOf(itemId: String): Int {
        val dragged = draggingItemId ?: return restingIndices.value[itemId] ?: -1
        if (itemId == dragged) return placeholderIndex
        val index = backgroundIndices.value[itemId] ?: return -1
        return if (index >= placeholderIndex) index + 1 else index
    }

    /**
     * TimePlan-style 1-D adapter entry point.
     * Moves only the insertion placeholder; repository order is still written
     * once on Drop by commitOrder().
     */
    fun movePlaceholderTo(targetIndex: Int): Boolean {
        if (!isDragging) return false
        val target = targetIndex.coerceIn(0, backgroundOrder.size)
        if (target == placeholderIndex) return false
        _placeholderIndex.value = target
        return true
    }

    fun begin(
        itemId: String,
        newMode: CountingReorderMode
    ) {
        if (canonicalItems.none { it.id == itemId }) return

        val order = restingOrder.toList()
        val sourceIndex = order.indexOf(itemId)
        if (sourceIndex < 0) return

        draggingItemId = itemId
        mode = newMode
        dragStartOrder = order

        backgroundOrder.clear()
        backgroundOrder.addAll(order.filter { it != itemId })
        _placeholderIndex.value = sourceIndex
        lastPlaceholderMoveAtMs = 0L
        lastDetailedPointerY = Float.NaN
        detailedDirection = 0
        detailedDragStartedAtMs = nowMillis()
        lastDetailedMoveAtMs = 0L
    }

    fun sync(latestItems: List<CountingItem>) {
        if (isDragging) return

        val latest = latestItems.sortedBy { it.order }
        val latestIds = latest.map { it.id }
        val latestById = latest.associateBy { it.id }
        val pending = pendingCommit

        if (
            pending != null &&
            latestIds != pending &&
            pending.all(latestById::containsKey)
        ) {
            val projected = pending.mapNotNull(latestById::get)
            if (canonicalItems.toList() != projected) {
                canonicalItems.clear()
                canonicalItems.addAll(projected)
            }
            if (restingOrder.toList() != pending) {
                restingOrder.clear()
                restingOrder.addAll(pending)
            }
            return
        }

        if (canonicalItems.toList() != latest) {
            canonicalItems.clear()
            canonicalItems.addAll(latest)
        }
        if (restingOrder.toList() != latestIds) {
            restingOrder.clear()
            restingOrder.addAll(latestIds)
        }

        if (pending != null && latestIds == pending) {
            pendingCommit = null
        }
    }

    fun cancel(latestItems: List<CountingItem>) {
        pendingCommit = null
        val latestById = latestItems.associateBy { it.id }

        restingOrder.clear()
        if (
            dragStartOrder.size == latestItems.size &&
            dragStartOrder.all(latestById::containsKey)
        ) {
            restingOrder.addAll(dragStartOrder)
        } else {
            restingOrder.addAll(
                latestItems.sortedBy { it.order }.map { it.id }
            )
        }

        finishSession()
    }

    fun commitOrder(): List<String> {
        val dragged = draggingItemId
        if (dragged == null) {
            return restingOrder.toList()
        }

        val result = backgroundOrder.toMutableList()
        result.add(
            placeholderIndex.coerceIn(0, result.size),
            dragged
        )

        pendingCommit = result.toList()
        restingOrder.clear()
        restingOrder.addAll(result)

        val byId = canonicalItems.associateBy { it.id }
        canonicalItems.clear()
        canonicalItems.addAll(
            result.mapNotNull(byId::get)
        )

        finishSession()
        return result
    }

    private fun finishSession() {
        draggingItemId = null
        mode = null
        backgroundOrder.clear()
        lastPlaceholderMoveAtMs = 0L
        lastDetailedPointerY = Float.NaN
        detailedDirection = 0
        detailedDragStartedAtMs = 0L
        lastDetailedMoveAtMs = 0L
    }

    private fun setPlaceholder(
        targetIndex: Int,
        nowMs: Long
    ): Boolean {
        if (!isDragging) return false
        val target =
            targetIndex.coerceIn(0, backgroundOrder.size)
        if (target == placeholderIndex) return false

        _placeholderIndex.value = target
        lastPlaceholderMoveAtMs = nowMs
        return true
    }

    /**
     * Detailed is a one-dimensional insertion problem.
     *
     * The slot occupied by the invisible dragged projection is the current
     * placeholder. Entering the leading portion of another slot changes the
     * placeholder directly to that slot index, so moving back to the original
     * position is fully reversible.
     */
    fun updateDetailed(
        pointerY: Float,
        slots: List<CountingReorderSlot>,
        nowMs: Long
    ): Boolean {
        if (!isDragging || slots.isEmpty()) return false

        if (!lastDetailedPointerY.isNaN()) {
            val delta = pointerY - lastDetailedPointerY
            when {
                delta < -1.5f -> detailedDirection = -1
                delta > 1.5f -> detailedDirection = 1
            }
        }
        lastDetailedPointerY = pointerY

        // Ignore the initial pointer/layout synchronization frames.
        // This prevents item #1 from visually plunging immediately on pickup.
        if (detailedDragStartedAtMs > 0L &&
            nowMs - detailedDragStartedAtMs < 72L
        ) return false

        // Give each accepted adjacent displacement a short, symmetric settle
        // interval. The dragged overlay remains pointer-driven; only the
        // background placeholder transaction is rate-limited.
        if (lastDetailedMoveAtMs > 0L &&
            nowMs - lastDetailedMoveAtMs < 46L
        ) return false

        val current = placeholderIndex
        val currentSlot = slots.firstOrNull { it.index == current }
        if (detailedDirection == 0) return false

        if (detailedDirection < 0) {
            val previous = slots.firstOrNull { it.index == current - 1 } ?: return false
            val boundary = if (currentSlot != null) {
                (currentSlot.centerY + previous.centerY) / 2f
            } else {
                previous.centerY + previous.height * 0.12f
            }
            val hysteresis = maxOf(8f, previous.height * 0.075f)

            if (pointerY < boundary - hysteresis) {
                val moved = setPlaceholder(current - 1, nowMs)
                if (moved) lastDetailedMoveAtMs = nowMs
                return moved
            }
            return false
        }

        val next = slots.firstOrNull { it.index == current + 1 } ?: return false
        val boundary = if (currentSlot != null) {
            (currentSlot.centerY + next.centerY) / 2f
        } else {
            next.centerY - next.height * 0.12f
        }
        val hysteresis = maxOf(8f, next.height * 0.075f)

        if (pointerY > boundary + hysteresis) {
            val moved = setPlaceholder(current + 1, nowMs)
            if (moved) lastDetailedMoveAtMs = nowMs
            return moved
        }
        return false
    }

    /**
     * Compact is a real 2-D cell selection problem.
     *
     * We identify the actual visible grid cell occupied by the overlay centre
     * instead of converting directions into ±1 steps. This makes left/right,
     * up/down and all four diagonals symmetric.
     *
     * A direct target index is safe here because canonical/background order is
     * not mutated; only placeholderIndex changes.
     */
    fun updateCompact(
        pointerX: Float,
        pointerY: Float,
        slots: List<CountingReorderSlot>,
        nowMs: Long
    ): Boolean {
        if (!isDragging || slots.isEmpty()) return false

        val target = slots
            .asSequence()
            .filter {
                // The overlay centre must genuinely enter a cell.
                // A small expansion removes dead gaps without letting
                // a distant cell steal the placeholder.
                pointerX >= it.centerX - it.width * 0.54f &&
                    pointerX <= it.centerX + it.width * 0.54f &&
                    pointerY >= it.centerY - it.height * 0.54f &&
                    pointerY <= it.centerY + it.height * 0.54f
            }
            .minByOrNull {
                val nx =
                    (pointerX - it.centerX) /
                        it.width.coerceAtLeast(1f)
                val ny =
                    (pointerY - it.centerY) /
                        it.height.coerceAtLeast(1f)
                nx * nx + ny * ny
            }
            ?: return false

        return setPlaceholder(target.index, nowMs)
    }
}

package com.seolhwa.armyrist.data

import android.content.Context
import com.seolhwa.armyrist.domain.*
import org.json.JSONArray
import org.json.JSONObject

class CountingRepository(context: Context) {
    private val prefs =
        context.getSharedPreferences("armyrist_stage1", Context.MODE_PRIVATE)
    private val key = "snapshot_v1"

    private val snapshots = GuardedSnapshotStore(
        readRaw = { prefs.getString(key, null) },
        writeRaw = { raw ->
            val editor = prefs.edit()
            if (raw == null) editor.remove(key) else editor.putString(key, raw)
            editor.commit()
        },
        decode = ::decodeSnapshot,
        encode = ::encodeSnapshot,
        onError = { reportStorageError(context.applicationContext, it) }
    )

    @Volatile
    private var sheets: List<CountingSheet> = snapshots.load(emptyList())

    @Synchronized
    fun reloadFromPersistence() {
        sheets = snapshots.load(emptyList(), sheets)
    }

    @Synchronized
    fun getSheets(): List<CountingSheet> =
        sheets.sortedByDescending { it.updatedAt }

    @Synchronized
    fun getSheet(id: String): CountingSheet? =
        sheets.firstOrNull { it.id == id }

    @Synchronized
    fun createSheet(): CountingSheet? {
        val sheet = CountingSheet()
        return if (saveSheets(sheets + sheet)) sheet else null
    }

    @Synchronized
    fun updateSheet(
        id: String,
        transform: (CountingSheet) -> CountingSheet
    ): CountingSheet? {
        val current = sheets.firstOrNull { it.id == id } ?: return null
        val next =
            transform(current).copy(updatedAt = System.currentTimeMillis())

        require(next.title.trim().isNotEmpty())
        require(
            next.items.all {
                it.quantity >= 0 &&
                    it.name.trim().isNotEmpty() &&
                    it.unit.trim().isNotEmpty()
            }
        )
        require(next.groups.all { it.name.trim().isNotEmpty() })

        val groupIds = next.groups.map { it.id }.toSet()
        require(next.items.all { it.groupId == null || it.groupId in groupIds })
        require(
            next.calculations.all {
                it.leftGroupId in groupIds && it.rightGroupId in groupIds
            }
        )

        return if (saveSheets(sheets.map { if (it.id == id) next else it })) next else null
    }

    @Synchronized
    fun renameSheet(id: String, title: String): Boolean {
        val normalized = DomainRules.normalizeRequired(title) ?: return false
        return updateSheet(id) { it.copy(title = normalized) } != null
    }

    @Synchronized
    fun deleteSheet(id: String) {
        saveSheets(sheets.filterNot { it.id == id })
    }

    /**
     * Common Trash snapshot contract for whole Counting sheets.
     * The payload owns the complete sheet graph: items, groups, calculations and memo.
     */
    @Synchronized
    fun exportSheetTrashPayload(id: String): String? {
        val sheet = getSheet(id) ?: return null
        return JSONObject()
            .put("schemaVersion", 1)
            .put("sheet", sheetToJson(sheet))
            .toString()
    }

    @Synchronized
    fun deleteSheetForTrash(id: String): Boolean {
        if (sheets.none { it.id == id }) return false
        return saveSheets(sheets.filterNot { it.id == id })
    }

    @Synchronized
    fun restoreSheetTrashPayload(payload: String): Boolean {
        val restored = runCatching {
            val root = JSONObject(payload)
            if (root.optInt("schemaVersion", -1) != 1) return@runCatching null
            sheetFromJson(root.getJSONObject("sheet"))
        }.getOrNull() ?: return false

        if (sheets.any { it.id == restored.id }) return false
        return saveSheets(sheets + restored)
    }

    @Synchronized
    fun addItem(
        sheetId: String,
        name: String,
        quantity: Int,
        unit: String,
        note: String,
        groupId: String?
    ): Boolean {
        val n = DomainRules.normalizeRequired(name) ?: return false
        val u = DomainRules.normalizeRequired(unit) ?: return false
        if (quantity < 0) return false

        val sheet = getSheet(sheetId) ?: return false
        if (groupId != null && sheet.groups.none { it.id == groupId }) {
            return false
        }

        val nextOrder = (sheet.items.maxOfOrNull { it.order } ?: -1) + 1
        val item = CountingItem(
            sheetId = sheetId,
            name = n,
            quantity = quantity,
            unit = u,
            note = note.trim(),
            groupId = groupId,
            order = nextOrder
        )

        return updateSheet(sheetId) {
            it.copy(items = it.items + item)
        } != null
    }

    @Synchronized
    fun editItem(
        sheetId: String,
        itemId: String,
        name: String,
        unit: String,
        note: String,
        groupId: String?
    ): Boolean {
        val n = DomainRules.normalizeRequired(name) ?: return false
        val u = DomainRules.normalizeRequired(unit) ?: return false
        val sheet = getSheet(sheetId) ?: return false
        if (groupId != null && sheet.groups.none { it.id == groupId }) {
            return false
        }

        return updateSheet(sheetId) { s ->
            s.copy(
                items = s.items.map {
                    if (it.id == itemId) {
                        it.copy(
                            name = n,
                            unit = u,
                            note = note.trim(),
                            groupId = groupId
                        )
                    } else {
                        it
                    }
                }
            )
        } != null
    }

    @Synchronized
    fun setQuantity(
        sheetId: String,
        itemId: String,
        quantity: Int
    ): Boolean {
        if (quantity < 0) return false
        return updateSheet(sheetId) { s ->
            s.copy(
                items = s.items.map {
                    if (it.id == itemId) it.copy(quantity = quantity) else it
                }
            )
        } != null
    }

    fun increment(sheetId: String, itemId: String) {
        val item =
            getSheet(sheetId)?.items?.firstOrNull { it.id == itemId } ?: return
        if (item.quantity < Int.MAX_VALUE) {
            setQuantity(sheetId, itemId, item.quantity + 1)
        }
    }

    fun decrement(sheetId: String, itemId: String) {
        val item =
            getSheet(sheetId)?.items?.firstOrNull { it.id == itemId } ?: return
        setQuantity(sheetId, itemId, (item.quantity - 1).coerceAtLeast(0))
    }

    @Synchronized
    fun deleteItem(sheetId: String, itemId: String) {
        updateSheet(sheetId) { s ->
            val normalized =
                s.items.filterNot { it.id == itemId }
                    .sortedBy { it.order }
                    .mapIndexed { index, item -> item.copy(order = index) }
            s.copy(items = normalized)
        }
    }

    @Synchronized
    fun moveItem(sheetId: String, itemId: String, delta: Int) {
        val sheet = getSheet(sheetId) ?: return
        val sorted = sheet.items.sortedBy { it.order }.toMutableList()
        val from = sorted.indexOfFirst { it.id == itemId }
        if (from < 0) return

        val to = (from + delta).coerceIn(0, sorted.lastIndex)
        if (from == to) return

        val item = sorted.removeAt(from)
        sorted.add(to, item)

        updateSheet(sheetId) {
            it.copy(
                items = sorted.mapIndexed { i, value ->
                    value.copy(order = i)
                }
            )
        }
    }

    @Synchronized
    fun reorderItems(sheetId: String, orderedIds: List<String>): Boolean {
        val sheet = getSheet(sheetId) ?: return false
        if (orderedIds.distinct().size != orderedIds.size) return false
        if (orderedIds.toSet() != sheet.items.map { it.id }.toSet()) return false

        val byId = sheet.items.associateBy { it.id }
        val reordered = orderedIds.mapIndexedNotNull { index, id ->
            byId[id]?.copy(order = index)
        }
        if (reordered.size != sheet.items.size) return false

        return updateSheet(sheetId) { it.copy(items = reordered) } != null
    }

    @Synchronized
    fun addGroup(
        sheetId: String,
        name: String,
        color: String = "#6750A4",
        showAggregate: Boolean = true
    ): Boolean {
        val n = DomainRules.normalizeRequired(name) ?: return false
        val sheet = getSheet(sheetId) ?: return false
        val order = (sheet.groups.maxOfOrNull { it.order } ?: -1) + 1

        val group = CountingGroup(
            sheetId = sheetId,
            name = n,
            order = order,
            color = color,
            showAggregate = showAggregate
        )

        return updateSheet(sheetId) {
            it.copy(groups = it.groups + group)
        } != null
    }

    @Synchronized
    fun renameGroup(
        sheetId: String,
        groupId: String,
        name: String,
        color: String? = null,
        showAggregate: Boolean? = null
    ): Boolean {
        val n = DomainRules.normalizeRequired(name) ?: return false

        return updateSheet(sheetId) { s ->
            s.copy(
                groups = s.groups.map {
                    if (it.id == groupId) {
                        it.copy(
                            name = n,
                            color = color ?: it.color,
                            showAggregate =
                                showAggregate ?: it.showAggregate
                        )
                    } else {
                        it
                    }
                }
            )
        } != null
    }

    @Synchronized
    fun setGroupShowAggregate(
        sheetId: String,
        groupId: String,
        showAggregate: Boolean
    ): Boolean =
        updateSheet(sheetId) { s ->
            s.copy(
                groups = s.groups.map {
                    if (it.id == groupId) {
                        it.copy(showAggregate = showAggregate)
                    } else {
                        it
                    }
                }
            )
        } != null

    @Synchronized
    fun assignItemsToGroup(
        sheetId: String,
        itemIds: Set<String>,
        groupId: String?
    ): Boolean {
        val sheet = getSheet(sheetId) ?: return false
        if (groupId != null && sheet.groups.none { it.id == groupId }) {
            return false
        }

        return updateSheet(sheetId) { s ->
            s.copy(
                items = s.items.map {
                    if (it.id in itemIds) it.copy(groupId = groupId) else it
                }
            )
        } != null
    }

    @Synchronized
    fun deleteGroup(sheetId: String, groupId: String) {
        updateSheet(sheetId) { s ->
            val groups =
                s.groups.filterNot { it.id == groupId }
                    .sortedBy { it.order }
                    .mapIndexed { i, g -> g.copy(order = i) }

            s.copy(
                groups = groups,
                items = s.items.map {
                    if (it.groupId == groupId) {
                        it.copy(groupId = null)
                    } else {
                        it
                    }
                },
                calculations = s.calculations.filterNot {
                    it.leftGroupId == groupId ||
                        it.rightGroupId == groupId
                }
            )
        }
    }

    @Synchronized
    fun addCalculation(
        sheetId: String,
        left: String,
        operator: CalculationOperator,
        right: String,
        name: String
    ): Boolean {
        val sheet = getSheet(sheetId) ?: return false
        if (
            sheet.groups.none { it.id == left } ||
            sheet.groups.none { it.id == right }
        ) {
            return false
        }

        val calculation = GroupCalculation(
            sheetId = sheetId,
            leftGroupId = left,
            operator = operator,
            rightGroupId = right,
            name = name.trim()
        )

        return updateSheet(sheetId) {
            it.copy(calculations = it.calculations + calculation)
        } != null
    }

    @Synchronized
    fun editCalculation(
        sheetId: String,
        calcId: String,
        left: String,
        operator: CalculationOperator,
        right: String,
        name: String
    ): Boolean {
        val sheet = getSheet(sheetId) ?: return false
        if (
            sheet.groups.none { it.id == left } ||
            sheet.groups.none { it.id == right }
        ) {
            return false
        }

        return updateSheet(sheetId) { s ->
            s.copy(
                calculations = s.calculations.map {
                    if (it.id == calcId) {
                        it.copy(
                            leftGroupId = left,
                            operator = operator,
                            rightGroupId = right,
                            name = name.trim()
                        )
                    } else {
                        it
                    }
                }
            )
        } != null
    }

    @Synchronized
    fun deleteCalculation(sheetId: String, calcId: String) {
        updateSheet(sheetId) {
            it.copy(
                calculations =
                    it.calculations.filterNot { calculation ->
                        calculation.id == calcId
                    }
            )
        }
    }

    @Synchronized
    fun setMemo(sheetId: String, memo: String) {
        updateSheet(sheetId) { it.copy(memo = memo) }
    }

    private fun saveSheets(next: List<CountingSheet>): Boolean {
        if (!snapshots.save(next)) return false
        sheets = next
        return true
    }

    private fun encodeSnapshot(values: List<CountingSheet>): String = JSONObject()
        .put("version", 2)
        .put("sheets", JSONArray().apply { values.forEach { put(sheetToJson(it)) } })
        .toString()

    private fun decodeSnapshot(raw: String): List<CountingSheet> {
        val root = JSONObject(raw)
        require(root.optInt("version", 1) in 1..2)
        val arr = root.getJSONArray("sheets")
        return List(arr.length()) { index -> sheetFromJson(arr.getJSONObject(index)) }
    }

    private fun sheetToJson(s: CountingSheet) =
        JSONObject()
            .put("id", s.id)
            .put("title", s.title)
            .put("memo", s.memo)
            .put("createdAt", s.createdAt)
            .put("updatedAt", s.updatedAt)
            .put(
                "items",
                JSONArray().apply {
                    s.items.forEach { put(itemToJson(it)) }
                }
            )
            .put(
                "groups",
                JSONArray().apply {
                    s.groups.forEach { put(groupToJson(it)) }
                }
            )
            .put(
                "calculations",
                JSONArray().apply {
                    s.calculations.forEach { put(calcToJson(it)) }
                }
            )

    private fun itemToJson(i: CountingItem) =
        JSONObject()
            .put("id", i.id)
            .put("sheetId", i.sheetId)
            .put("name", i.name)
            .put("quantity", i.quantity)
            .put("unit", i.unit)
            .put("note", i.note)
            .put("groupId", i.groupId ?: JSONObject.NULL)
            .put("order", i.order)

    private fun groupToJson(g: CountingGroup) =
        JSONObject()
            .put("id", g.id)
            .put("sheetId", g.sheetId)
            .put("name", g.name)
            .put("order", g.order)
            .put("color", g.color)
            .put("showAggregate", g.showAggregate)

    private fun calcToJson(c: GroupCalculation) =
        JSONObject()
            .put("id", c.id)
            .put("sheetId", c.sheetId)
            .put("leftGroupId", c.leftGroupId)
            .put("operator", c.operator.name)
            .put("rightGroupId", c.rightGroupId)
            .put("name", c.name)

    private fun sheetFromJson(o: JSONObject): CountingSheet {
        val items = o.getJSONArray("items")
        val groups = o.getJSONArray("groups")
        val calculations = o.getJSONArray("calculations")

        return CountingSheet(
            id = o.getString("id"),
            title = o.getString("title"),
            memo = o.optString("memo", ""),
            items = List(items.length()) {
                itemFromJson(items.getJSONObject(it))
            },
            groups = List(groups.length()) {
                groupFromJson(groups.getJSONObject(it))
            },
            calculations = List(calculations.length()) {
                calcFromJson(calculations.getJSONObject(it))
            },
            createdAt = o.getLong("createdAt"),
            updatedAt = o.getLong("updatedAt")
        )
    }

    private fun itemFromJson(o: JSONObject) =
        CountingItem(
            id = o.getString("id"),
            sheetId = o.getString("sheetId"),
            name = o.getString("name"),
            quantity = o.getInt("quantity"),
            unit = o.getString("unit"),
            note = o.optString("note", ""),
            groupId =
                if (o.isNull("groupId")) null
                else o.getString("groupId"),
            order = o.getInt("order")
        )

    private fun groupFromJson(o: JSONObject) =
        CountingGroup(
            id = o.getString("id"),
            sheetId = o.getString("sheetId"),
            name = o.getString("name"),
            order = o.getInt("order"),
            color = o.optString("color", "#6750A4"),
            // Legacy Stage 1/2 groups have no field: migrate as visible.
            showAggregate = o.optBoolean("showAggregate", true)
        )

    private fun calcFromJson(o: JSONObject) =
        GroupCalculation(
            id = o.getString("id"),
            sheetId = o.getString("sheetId"),
            leftGroupId = o.getString("leftGroupId"),
            operator =
                CalculationOperator.valueOf(o.getString("operator")),
            rightGroupId = o.getString("rightGroupId"),
            name = o.optString("name", "")
        )
}

package com.seolhwa.armyrist.notification

import android.Manifest
import android.app.AlarmManager
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.media.AudioAttributes
import android.media.RingtoneManager
import com.seolhwa.armyrist.TimePlanExecutionActivity
import com.seolhwa.armyrist.timeplan.v3.data.DateAwareTimePlanRepository
import com.seolhwa.armyrist.timeplan.v3.domain.ActionCompletionState
import com.seolhwa.armyrist.timeplan.v3.domain.DateAwareTimePlan
import com.seolhwa.armyrist.timeplan.v3.domain.TimePlanActionItem
import java.time.ZoneId

object TimePlanActionNotificationManager {
    private const val CHANNEL_ID_SIMPLE = "timeplan_action_reminder_simple_v2"
    private const val CHANNEL_ID_MUSIC = "timeplan_action_reminder_music_loop_v3"
    private const val PREFS = "armyrist_timeplan_action_alarms"
    private const val KEY_IDS = "scheduled_ids"

    const val EXTRA_PLAN_ID = "planId"
    const val EXTRA_ACTION_ID = "actionId"

    fun notificationPermissionGranted(context: Context): Boolean =
        Build.VERSION.SDK_INT < 33 ||
            context.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED

    fun createChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val manager = context.getSystemService(NotificationManager::class.java)
            if (manager.getNotificationChannel(CHANNEL_ID_SIMPLE) == null) {
                manager.createNotificationChannel(NotificationChannel(CHANNEL_ID_SIMPLE, "시간계획 · 간단한 알림", NotificationManager.IMPORTANCE_HIGH).apply {
                    description = "짧은 기본 알림음으로 시간계획 실시사항을 알립니다."
                })
            }
            if (manager.getNotificationChannel(CHANNEL_ID_MUSIC) == null) {
                manager.createNotificationChannel(
                    NotificationChannel(
                        CHANNEL_ID_MUSIC,
                        "시간계획 · 음악 알림",
                        NotificationManager.IMPORTANCE_HIGH
                    ).apply {
                        description = "사용자가 중지할 때까지 반복되는 시간계획 음악 알림입니다."
                        // Sound is played by TimePlanMusicAlarmService so it can loop
                        // until explicit acknowledgement.
                        setSound(null, null)
                        enableVibration(true)
                    }
                )
            }
        }
    }

    fun channelId(action: TimePlanActionItem): String =
        if (action.notificationMode == com.seolhwa.armyrist.timeplan.v3.domain.ActionNotificationMode.MUSIC) CHANNEL_ID_MUSIC else CHANNEL_ID_SIMPLE

    fun musicChannelId(): String = CHANNEL_ID_MUSIC

    fun notificationId(planId: String, actionId: String): Int =
        requestCode(planId, actionId)

    fun startMusicAlarm(context: Context, planId: String, actionId: String) {
        val intent = Intent(context, TimePlanMusicAlarmService::class.java).apply {
            action = TimePlanMusicAlarmService.ACTION_START
            putExtra(EXTRA_PLAN_ID, planId)
            putExtra(EXTRA_ACTION_ID, actionId)
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            context.startForegroundService(intent)
        } else {
            context.startService(intent)
        }
    }

    fun stopMusicAlarm(context: Context, planId: String, actionId: String) {
        // Never start an idle/background service merely to request a stop.
        TimePlanMusicAlarmService.stopIfActive(planId, actionId)
    }

    fun stopMusicPendingIntent(
        context: Context,
        planId: String,
        actionId: String
    ): PendingIntent =
        PendingIntent.getService(
            context,
            requestCode(planId, actionId) xor 0x40000000,
            Intent(context, TimePlanMusicAlarmService::class.java).apply {
                action = TimePlanMusicAlarmService.ACTION_STOP
                putExtra(EXTRA_PLAN_ID, planId)
                putExtra(EXTRA_ACTION_ID, actionId)
            },
            PendingIntent.FLAG_UPDATE_CURRENT or immutableFlag()
        )

    fun isEligible(
        context: Context,
        plan: DateAwareTimePlan,
        action: TimePlanActionItem,
        nowMillis: Long = System.currentTimeMillis()
    ): Boolean {
        val trigger = action.scheduledDateTime
            .atZone(ZoneId.systemDefault())
            .toInstant()
            .toEpochMilli()
        return plan.dateDisplayMode !=
            com.seolhwa.armyrist.timeplan.v3.domain.TimePlanDateDisplayMode.RELATIVE_D_DAY &&
            action.notificationMode != com.seolhwa.armyrist.timeplan.v3.domain.ActionNotificationMode.NONE &&
            action.completionState == ActionCompletionState.INCOMPLETE &&
            trigger > nowMillis &&
            notificationPermissionGranted(context)
    }

    fun reconcile(context: Context, repository: DateAwareTimePlanRepository) {
        if (!repository.storageReadable) return
        createChannel(context)
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val previously = prefs.getStringSet(KEY_IDS, emptySet()).orEmpty().toSet()
        val tracked = mutableSetOf<String>()
        val now = java.time.LocalDateTime.now()
        val permission = notificationPermissionGranted(context)

        repository.getPlans().forEach { plan ->
            plan.actions.forEach { action ->
                val storedKey = key(plan.id, action.id)
                when (TimePlanAlarmPolicy.disposition(plan, action, now, permission)) {
                    AlarmDisposition.SCHEDULE -> {
                        schedule(context, plan, action)
                        tracked += storedKey
                    }
                    AlarmDisposition.PRESERVE_DELIVERED -> {
                        // Keep tracking fired actions, so deletion/completion on a
                        // subsequent reconcile can still clear their notification.
                        cancelScheduledOnly(context, plan.id, action.id)
                        if (action.notificationMode != com.seolhwa.armyrist.timeplan.v3.domain.ActionNotificationMode.MUSIC) {
                            stopMusicAlarm(context, plan.id, action.id)
                        }
                        tracked += storedKey
                    }
                    AlarmDisposition.CLEAR -> cancel(context, plan.id, action.id)
                }
            }
        }

        (previously - tracked).forEach { stored ->
            val parts = stored.split('|', limit = 2)
            if (parts.size == 2) cancel(context, parts[0], parts[1])
        }
        prefs.edit().putStringSet(KEY_IDS, tracked).apply()
    }

    fun schedule(context: Context, plan: DateAwareTimePlan, action: TimePlanActionItem): Boolean {
        if (!isEligible(context, plan, action)) {
            cancel(context, plan.id, action.id)
            return false
        }

        val triggerAt = action.scheduledDateTime
            .atZone(ZoneId.systemDefault())
            .toInstant()
            .toEpochMilli()
        val manager = context.getSystemService(AlarmManager::class.java)
        cancel(context, plan.id, action.id)
        val pending = alarmPendingIntent(context, plan.id, action.id)

        // Reminder contract: deliver at the scheduled time even while the screen is off
        // whenever Android grants exact-alarm capability. If the user/device does not
        // grant that capability, retain a safe inexact while-idle fallback instead of crashing.
        val exactAllowed =
            Build.VERSION.SDK_INT < Build.VERSION_CODES.S || manager.canScheduleExactAlarms()

        when {
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.M && exactAllowed ->
                manager.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, triggerAt, pending)
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.M ->
                manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP, triggerAt, pending)
            else ->
                manager.set(AlarmManager.RTC_WAKEUP, triggerAt, pending)
        }
        return true
    }

    /**
     * Cancels only future AlarmManager delivery; delivered notifications are retained.
     * It intentionally does NOT stop an already-running MUSIC foreground service.
     *
     * This is used by reconcile/schedule so merely opening Armyrist after the
     * scheduled time cannot silence a music alarm that is currently ringing.
     */
    private fun cancelScheduledOnly(context: Context, planId: String, actionId: String) {
        val manager = context.getSystemService(AlarmManager::class.java)
        PendingIntent.getBroadcast(
            context,
            requestCode(planId, actionId),
            Intent(context, TimePlanActionAlarmReceiver::class.java)
                .setAction("com.seolhwa.armyrist.TIMEPLAN_ACTION_ALARM"),
            PendingIntent.FLAG_NO_CREATE or immutableFlag()
        )?.let {
            manager.cancel(it)
            it.cancel()
        }
    }

    fun cancel(context: Context, planId: String, actionId: String) {
        cancelScheduledOnly(context, planId, actionId)
        context.getSystemService(NotificationManager::class.java)
            .cancel(requestCode(planId, actionId))
        stopMusicAlarm(context, planId, actionId)
    }

    fun openActionPendingIntent(context: Context, planId: String, actionId: String): PendingIntent =
        PendingIntent.getActivity(
            context,
            requestCode(planId, actionId),
            Intent(context, TimePlanExecutionActivity::class.java).apply {
                putExtra(TimePlanExecutionActivity.EXTRA_PLAN_ID, planId)
                putExtra(TimePlanExecutionActivity.EXTRA_MODE, TimePlanExecutionActivity.MODE_EXECUTE)
                putExtra(EXTRA_ACTION_ID, actionId)
            },
            PendingIntent.FLAG_UPDATE_CURRENT or immutableFlag()
        )

    private fun alarmPendingIntent(context: Context, planId: String, actionId: String): PendingIntent =
        PendingIntent.getBroadcast(
            context,
            requestCode(planId, actionId),
            Intent(context, TimePlanActionAlarmReceiver::class.java).apply {
                action = "com.seolhwa.armyrist.TIMEPLAN_ACTION_ALARM"
                putExtra(EXTRA_PLAN_ID, planId)
                putExtra(EXTRA_ACTION_ID, actionId)
            },
            PendingIntent.FLAG_UPDATE_CURRENT or immutableFlag()
        )

    private fun requestCode(planId: String, actionId: String): Int =
        ("$planId|$actionId".hashCode() and 0x7fffffff)

    private fun key(planId: String, actionId: String): String = "$planId|$actionId"

    private fun immutableFlag(): Int =
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) PendingIntent.FLAG_IMMUTABLE else 0
}

package com.seolhwa.armyrist.notification

import android.app.Notification
import android.app.Service
import android.content.Intent
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.media.RingtoneManager
import android.os.IBinder
import androidx.core.app.NotificationCompat
import com.seolhwa.armyrist.timeplan.v3.data.DateAwareTimePlanRepository
import com.seolhwa.armyrist.timeplan.v3.domain.ActionCompletionState
import com.seolhwa.armyrist.timeplan.v3.domain.ActionNotificationMode
import java.time.format.DateTimeFormatter

class TimePlanMusicAlarmService : Service() {
    private var player: MediaPlayer? = null
    private var activePlanId: String? = null
    private var activeActionId: String? = null

    override fun onCreate() {
        super.onCreate()
        runningService = this
        TimePlanActionNotificationManager.createChannel(this)
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_STOP -> {
                val planId = intent.getStringExtra(TimePlanActionNotificationManager.EXTRA_PLAN_ID)
                val actionId = intent.getStringExtra(TimePlanActionNotificationManager.EXTRA_ACTION_ID)

                if (
                    planId == null || actionId == null ||
                    (planId == activePlanId && actionId == activeActionId)
                ) {
                    stopAlarm()
                }
                return START_NOT_STICKY
            }

            ACTION_START -> {
                val planId =
                    intent.getStringExtra(TimePlanActionNotificationManager.EXTRA_PLAN_ID)
                        ?: return START_NOT_STICKY
                val actionId =
                    intent.getStringExtra(TimePlanActionNotificationManager.EXTRA_ACTION_ID)
                        ?: return START_NOT_STICKY

                val repository = DateAwareTimePlanRepository(applicationContext)
                val plan = repository.getPlan(planId) ?: return START_NOT_STICKY
                val action = plan.actions.firstOrNull { it.id == actionId }
                    ?: return START_NOT_STICKY

                if (
                    action.notificationMode != ActionNotificationMode.MUSIC ||
                    action.completionState != ActionCompletionState.INCOMPLETE ||
                    !TimePlanActionNotificationManager.notificationPermissionGranted(this)
                ) {
                    return START_NOT_STICKY
                }

                activePlanId = planId
                activeActionId = actionId

                val notification = NotificationCompat.Builder(
                    this,
                    TimePlanActionNotificationManager.musicChannelId()
                )
                    .setSmallIcon(android.R.drawable.ic_lock_idle_alarm)
                    .setContentTitle(action.content)
                    .setContentText(
                        "${plan.title} · ${
                            action.scheduledDateTime.format(
                                DateTimeFormatter.ofPattern("HH:mm")
                            )
                        } 예정"
                    )
                    .setPriority(NotificationCompat.PRIORITY_HIGH)
                    .setCategory(NotificationCompat.CATEGORY_ALARM)
                    .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                    .setOngoing(true)
                    .setAutoCancel(false)
                    .setContentIntent(
                        TimePlanActionNotificationManager.openActionPendingIntent(
                            this,
                            plan.id,
                            action.id
                        )
                    )
                    .addAction(
                        android.R.drawable.ic_media_pause,
                        "알림 중지",
                        TimePlanActionNotificationManager.stopMusicPendingIntent(
                            this,
                            plan.id,
                            action.id
                        )
                    )
                    .build()

                startForeground(
                    TimePlanActionNotificationManager.notificationId(plan.id, action.id),
                    notification
                )
                startLoopingAlarm()
            }
        }
        return START_NOT_STICKY
    }

    private fun startLoopingAlarm() {
        if (player?.isPlaying == true) return

        player?.release()
        player = MediaPlayer().apply {
            setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_ALARM)
                    .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                    .build()
            )
            val alarmUri =
                RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM)
                    ?: RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION)
            setDataSource(applicationContext, alarmUri)
            isLooping = true
            prepare()
            start()
        }
    }

    private fun stopAlarm() {
        player?.runCatching {
            if (isPlaying) stop()
        }
        player?.release()
        player = null
        activePlanId = null
        activeActionId = null
        if (android.os.Build.VERSION.SDK_INT >= 24) {
            stopForeground(STOP_FOREGROUND_REMOVE)
        } else {
            @Suppress("DEPRECATION")
            stopForeground(true)
        }
        stopSelf()
    }

    override fun onDestroy() {
        if (runningService === this) runningService = null
        player?.release()
        player = null
        super.onDestroy()
    }

    override fun onBind(intent: Intent?): IBinder? = null

    companion object {
        @Volatile private var runningService: TimePlanMusicAlarmService? = null

        internal fun stopIfActive(planId: String, actionId: String) {
            android.os.Handler(android.os.Looper.getMainLooper()).post {
                val service = runningService
                if (service != null && service.activePlanId == planId && service.activeActionId == actionId) {
                    service.stopAlarm()
                }
            }
        }

        const val ACTION_START =
            "com.seolhwa.armyrist.TIMEPLAN_MUSIC_ALARM_START"
        const val ACTION_STOP =
            "com.seolhwa.armyrist.TIMEPLAN_MUSIC_ALARM_STOP"
    }
}

package com.seolhwa.armyrist.stage2.data

import android.content.Context
import com.seolhwa.armyrist.stage2.domain.*
import org.json.JSONArray
import org.json.JSONObject
import java.util.UUID
import com.seolhwa.armyrist.ui.reorderedByIds

class CoreSuiteRepository(context: Context) {
    private val prefs = context.getSharedPreferences(
        "armyrist_stage2_core",
        Context.MODE_PRIVATE
    )

    private val snapshotKey = "snapshot_v1"

    private var checklists: List<Checklist> = emptyList()
    private var timePlans: List<TimePlan> = emptyList()
    private var userProfile: UserProfile = UserProfile()
    private var reportTemplates: List<ReportTemplate> = emptyList()

    init {
        load()
    }

    @Synchronized
    fun reloadFromPersistence() {
        checklists = emptyList()
        timePlans = emptyList()
        userProfile = UserProfile()
        reportTemplates = emptyList()
        load()
    }

    @Synchronized
    fun getChecklists(): List<Checklist> =
        checklists.sortedByDescending { it.updatedAt }

    @Synchronized
    fun getChecklist(id: String): Checklist? =
        checklists.firstOrNull { it.id == id }

    @Synchronized
    fun createChecklist(): Checklist {
        val checklist = Checklist()
        checklists = checklists + checklist
        persist()
        return checklist
    }

    @Synchronized
    fun updateChecklist(
        id: String,
        transform: (Checklist) -> Checklist
    ): Checklist? {
        val current = getChecklist(id) ?: return null
        val next = transform(current).copy(
            updatedAt = System.currentTimeMillis()
        )

        require(next.title.trim().isNotEmpty())
        require(next.groups.all { it.name.trim().isNotEmpty() })
        require(next.items.all { it.name.trim().isNotEmpty() })
        require(next.deletedItems.all { it.name.trim().isNotEmpty() })
        require(next.items.all { item ->
            !item.notificationEnabled ||
                (item.scheduledTimeMinutes != null && item.scheduledTimeMinutes in 0..1439)
        })

        val groupIds = next.groups.map { it.id }.toSet()
        require(next.items.all {
            it.groupId == null || it.groupId in groupIds
        })

        checklists = checklists.map {
            if (it.id == id) next else it
        }
        persist()
        return next
    }

    @Synchronized
    fun renameChecklist(id: String, title: String): Boolean {
        val normalized = title.trim().takeIf { it.isNotEmpty() } ?: return false
        return updateChecklist(id) { it.copy(title = normalized) } != null
    }

    @Synchronized
    fun deleteChecklist(id: String) {
        checklists = checklists.filterNot { it.id == id }
        persist()
    }

    /**
     * Common Trash payload for a whole Checklist.
     * The existing checklist JSON serializer owns groups, active/deleted items,
     * memo and notification settings, so no parallel schema is invented here.
     */
    @Synchronized
    fun exportChecklistTrashPayload(id: String): String? {
        val checklist = getChecklist(id) ?: return null
        return JSONObject()
            .put("schemaVersion", 1)
            .put("checklist", checklistToJson(checklist))
            .toString()
    }

    @Synchronized
    fun deleteChecklistForTrash(id: String): Boolean {
        if (checklists.none { it.id == id }) return false

        val before = checklists
        checklists = checklists.filterNot { it.id == id }

        if (persistChecked()) return true

        checklists = before
        return false
    }

    @Synchronized
    fun restoreChecklistTrashPayload(payload: String): Boolean {
        val restored = runCatching {
            val root = JSONObject(payload)
            if (root.optInt("schemaVersion", -1) != 1) return@runCatching null
            checklistFromJson(root.getJSONObject("checklist"))
        }.getOrNull() ?: return false

        if (checklists.any { it.id == restored.id }) return false

        val before = checklists
        checklists = checklists + restored

        if (persistChecked()) return true

        checklists = before
        return false
    }

    @Synchronized
    fun addChecklistItem(
        checklistId: String,
        name: String,
        note: String = "",
        groupId: String? = null,
        notificationEnabled: Boolean = false,
        scheduledTimeMinutes: Int? = null,
        notificationSoundUri: String? = null
    ): Boolean {
        val normalized = name.trim().takeIf { it.isNotEmpty() } ?: return false
        val checklist = getChecklist(checklistId) ?: return false

        if (groupId != null && checklist.groups.none { it.id == groupId }) {
            return false
        }

        val order = (checklist.items.maxOfOrNull { it.order } ?: -1) + 1
        val item = ChecklistItem(
            checklistId = checklistId,
            groupId = groupId,
            order = order,
            name = normalized,
            note = note.trim(),
            notificationEnabled = notificationEnabled,
            scheduledTimeMinutes = scheduledTimeMinutes,
            notificationSoundUri = notificationSoundUri
        )

        return updateChecklist(checklistId) {
            it.copy(items = it.items + item)
        } != null
    }

    @Synchronized
    fun editChecklistItem(
        checklistId: String,
        itemId: String,
        name: String,
        note: String,
        groupId: String?,
        notificationEnabled: Boolean = false,
        scheduledTimeMinutes: Int? = null,
        notificationSoundUri: String? = null
    ): Boolean {
        val normalized = name.trim().takeIf { it.isNotEmpty() } ?: return false
        val checklist = getChecklist(checklistId) ?: return false

        if (groupId != null && checklist.groups.none { it.id == groupId }) {
            return false
        }

        return updateChecklist(checklistId) { current ->
            current.copy(
                items = current.items.map {
                    if (it.id == itemId) {
                        it.copy(
                            name = normalized,
                            note = note.trim(),
                            groupId = groupId,
                            notificationEnabled = notificationEnabled,
                            scheduledTimeMinutes = scheduledTimeMinutes,
                            notificationSoundUri = notificationSoundUri
                        )
                    } else it
                }
            )
        } != null
    }

    @Synchronized
    fun setChecklistNotificationSoundForEnabledItems(
        checklistId: String,
        notificationSoundUri: String?
    ): Boolean =
        updateChecklist(checklistId) { current ->
            current.copy(
                items = current.items.map { item ->
                    if (item.notificationEnabled) {
                        item.copy(notificationSoundUri = notificationSoundUri)
                    } else {
                        item
                    }
                }
            )
        } != null

    @Synchronized
    fun setChecklistStatus(
        checklistId: String,
        itemId: String,
        status: ChecklistStatus
    ): Boolean =
        updateChecklist(checklistId) { current ->
            current.copy(
                items = current.items.map {
                    if (it.id == itemId) it.copy(status = status) else it
                }
            )
        } != null

    @Synchronized
    fun trashChecklistItem(checklistId: String, itemId: String): Boolean {
        val checklist = getChecklist(checklistId) ?: return false
        val target = checklist.items.firstOrNull { it.id == itemId } ?: return false

        return updateChecklist(checklistId) { current ->
            current.copy(
                items = current.items
                    .filterNot { it.id == itemId }
                    .sortedBy { it.order }
                    .mapIndexed { index, item ->
                        item.copy(order = index)
                    },
                deletedItems = current.deletedItems
                    .filterNot { it.id == itemId } + target
            )
        } != null
    }

    @Synchronized
    fun restoreChecklistItem(checklistId: String, itemId: String): Boolean {
        val checklist = getChecklist(checklistId) ?: return false
        val target = checklist.deletedItems.firstOrNull { it.id == itemId } ?: return false

        val restoredGroupId = target.groupId?.takeIf { groupId ->
            checklist.groups.any { it.id == groupId }
        }

        val active = checklist.items.sortedBy { it.order }.toMutableList()
        val insertIndex = target.order.coerceIn(0, active.size)
        active.add(insertIndex, target.copy(groupId = restoredGroupId))

        return updateChecklist(checklistId) { current ->
            current.copy(
                items = active.mapIndexed { index, item ->
                    item.copy(order = index)
                },
                deletedItems = current.deletedItems.filterNot { it.id == itemId }
            )
        } != null
    }

    @Synchronized
    fun permanentlyDeleteChecklistItem(checklistId: String, itemId: String): Boolean =
        updateChecklist(checklistId) { current ->
            current.copy(
                deletedItems = current.deletedItems.filterNot { it.id == itemId }
            )
        } != null

    @Synchronized
    fun moveChecklistItem(
        checklistId: String,
        itemId: String,
        delta: Int
    ) {
        val checklist = getChecklist(checklistId) ?: return
        val ordered = checklist.items.sortedBy { it.order }.toMutableList()
        val from = ordered.indexOfFirst { it.id == itemId }
        if (from < 0) return

        val to = (from + delta).coerceIn(0, ordered.lastIndex)
        if (from == to) return

        val item = ordered.removeAt(from)
        ordered.add(to, item)

        updateChecklist(checklistId) {
            it.copy(
                items = ordered.mapIndexed { index, value ->
                    value.copy(order = index)
                }
            )
        }
    }

    /** Dragging is a UI draft; write the complete final order once on drop. */
    @Synchronized
    fun reorderChecklistItems(checklistId: String, ids: List<String>): Boolean {
        val checklist = getChecklist(checklistId) ?: return false
        val ordered = reorderedByIds(checklist.items, ids) { it.id } ?: return false
        if (checklist.items.sortedBy { it.order }.map { it.id } == ids) return true
        val before = checklists
        val oldRaw = prefs.getString(snapshotKey, null)
        val next = checklist.copy(
            items = ordered.mapIndexed { index, item -> item.copy(order = index) },
            updatedAt = System.currentTimeMillis()
        )
        checklists = checklists.map { if (it.id == checklistId) next else it }
        if (runCatching { persistChecked() }.getOrDefault(false)) return true
        checklists = before
        runCatching {
            val editor = prefs.edit()
            if (oldRaw == null) editor.remove(snapshotKey) else editor.putString(snapshotKey, oldRaw)
            editor.commit()
        }
        return false
    }

    @Synchronized
    fun addChecklistGroup(
        checklistId: String,
        name: String,
        color: String = "#6750A4"
    ): Boolean {
        val normalized = name.trim().takeIf { it.isNotEmpty() } ?: return false
        val checklist = getChecklist(checklistId) ?: return false
        val order = (checklist.groups.maxOfOrNull { it.order } ?: -1) + 1

        return updateChecklist(checklistId) {
            it.copy(
                groups = it.groups + ChecklistGroup(
                    checklistId = checklistId,
                    name = normalized,
                    order = order,
                    color = color
                )
            )
        } != null
    }

    @Synchronized
    fun setChecklistGroupColor(
        checklistId: String,
        groupId: String,
        color: String
    ): Boolean =
        updateChecklist(checklistId) { current ->
            current.copy(
                groups = current.groups.map {
                    if (it.id == groupId) it.copy(color = color) else it
                }
            )
        } != null

    @Synchronized
    fun assignChecklistItemsToGroup(
        checklistId: String,
        itemIds: Set<String>,
        groupId: String?
    ): Boolean {
        val checklist = getChecklist(checklistId) ?: return false
        if (groupId != null && checklist.groups.none { it.id == groupId }) return false
        if (itemIds.isEmpty()) return true

        return updateChecklist(checklistId) { current ->
            current.copy(
                items = current.items.map { item ->
                    if (item.id in itemIds) item.copy(groupId = groupId) else item
                }
            )
        } != null
    }

    @Synchronized
    fun renameChecklistGroup(
        checklistId: String,
        groupId: String,
        name: String
    ): Boolean {
        val normalized = name.trim().takeIf { it.isNotEmpty() } ?: return false

        return updateChecklist(checklistId) { current ->
            current.copy(
                groups = current.groups.map {
                    if (it.id == groupId) it.copy(name = normalized) else it
                }
            )
        } != null
    }

    @Synchronized
    fun deleteChecklistGroup(checklistId: String, groupId: String) {
        updateChecklist(checklistId) { current ->
            current.copy(
                groups = current.groups
                    .filterNot { it.id == groupId }
                    .sortedBy { it.order }
                    .mapIndexed { index, group ->
                        group.copy(order = index)
                    },
                items = current.items.map {
                    if (it.groupId == groupId) it.copy(groupId = null) else it
                }
            )
        }
    }

    @Synchronized
    fun resetChecklistStatuses(checklistId: String) {
        updateChecklist(checklistId) {
            it.copy(items = ChecklistRules.resetStatuses(it.items))
        }
    }

    @Synchronized
    fun setChecklistMemo(checklistId: String, memo: String) {
        updateChecklist(checklistId) {
            it.copy(memo = memo)
        }
    }

    @Synchronized
    fun getTimePlans(): List<TimePlan> =
        timePlans.sortedByDescending { it.updatedAt }

    @Synchronized
    fun getTimePlan(id: String): TimePlan? =
        timePlans.firstOrNull { it.id == id }

    @Synchronized
    fun createTimePlan(): TimePlan {
        val planId = UUID.randomUUID().toString()
        val now = System.currentTimeMillis()

        val plan = TimePlan(
            id = planId,
            points = listOf(
                TimePoint(
                    planId = planId,
                    order = 0,
                    name = "시작",
                    timeMinutes = null
                ),
                TimePoint(
                    planId = planId,
                    order = 1,
                    name = "종료",
                    timeMinutes = null
                )
            ),
            createdAt = now,
            updatedAt = now
        )

        timePlans = timePlans + plan
        persist()
        return plan
    }

    @Synchronized
    fun updateTimePlan(
        id: String,
        transform: (TimePlan) -> TimePlan
    ): TimePlan? {
        val current = getTimePlan(id) ?: return null
        val next = transform(current).copy(
            updatedAt = System.currentTimeMillis()
        )

        require(next.title.trim().isNotEmpty())
        require(next.points.size >= 2)
        require(next.points.all { it.name.trim().isNotEmpty() })
        require(next.points.all {
            it.timeMinutes == null || it.timeMinutes in 0..1439
        })

        val definedPoints = next.points.filter { it.timeMinutes != null }
        if (definedPoints.size == next.points.size) {
            require(TimePlanRules.derive(next.points) != null)
        }

        timePlans = timePlans.map {
            if (it.id == id) next else it
        }
        persist()
        return next
    }

    @Synchronized
    fun renameTimePlan(id: String, title: String): Boolean {
        val normalized = title.trim().takeIf { it.isNotEmpty() } ?: return false
        return updateTimePlan(id) { it.copy(title = normalized) } != null
    }

    @Synchronized
    fun deleteTimePlan(id: String) {
        timePlans = timePlans.filterNot { it.id == id }
        persist()
    }

    @Synchronized
    fun setUserProfile(displayName: String) {
        userProfile = UserProfile(displayName = displayName)
        persist()
    }

    @Synchronized
    fun getUserProfile(): UserProfile = userProfile

    @Synchronized
    fun getReportTemplates(): List<ReportTemplate> =
        reportTemplates.sortedBy { it.order }

    @Synchronized
    fun getReportTemplate(id: String): ReportTemplate? =
        reportTemplates.firstOrNull { it.id == id }

    @Synchronized
    fun createReportTemplate(
        name: String,
        body: String = ""
    ): ReportTemplate? {
        val normalized = name.trim().takeIf { it.isNotEmpty() } ?: return null
        val order = (reportTemplates.maxOfOrNull { it.order } ?: -1) + 1

        val template = ReportTemplate(
            name = normalized,
            body = body,
            order = order
        )

        reportTemplates = reportTemplates + template
        persist()
        return template
    }

    @Synchronized
    fun updateReportTemplate(
        id: String,
        name: String,
        body: String
    ): Boolean {
        val normalized = name.trim().takeIf { it.isNotEmpty() } ?: return false
        if (reportTemplates.none { it.id == id }) return false

        reportTemplates = reportTemplates.map {
            if (it.id == id) {
                it.copy(name = normalized, body = body)
            } else it
        }
        persist()
        return true
    }

    @Synchronized
    fun setDefaultTemplate(id: String?) {
        reportTemplates = reportTemplates.map {
            it.copy(isDefault = id != null && it.id == id)
        }
        persist()
    }

    @Synchronized
    fun deleteReportTemplate(id: String) {
        reportTemplates = reportTemplates
            .filterNot { it.id == id }
            .sortedBy { it.order }
            .mapIndexed { index, template ->
                template.copy(order = index)
            }
        persist()
    }

    private fun persist() {
        persistChecked()
    }

    private fun persistChecked(): Boolean {
        val root = JSONObject()
            .put("version", 1)
            .put("checklists", JSONArray().apply {
                checklists.forEach { put(checklistToJson(it)) }
            })
            .put("timePlans", JSONArray().apply {
                timePlans.forEach { put(timePlanToJson(it)) }
            })
            .put("userProfile", JSONObject().apply {
                put("displayName", userProfile.displayName)
            })
            .put("reportTemplates", JSONArray().apply {
                reportTemplates.forEach { put(templateToJson(it)) }
            })

        return prefs.edit()
            .putString(snapshotKey, root.toString())
            .commit()
    }

    private fun load() {
        val raw = prefs.getString(snapshotKey, null) ?: return

        runCatching {
            val root = JSONObject(raw)

            val checklistArray = root.optJSONArray("checklists") ?: JSONArray()
            checklists = List(checklistArray.length()) {
                checklistFromJson(checklistArray.getJSONObject(it))
            }

            val timePlanArray = root.optJSONArray("timePlans") ?: JSONArray()
            timePlans = List(timePlanArray.length()) {
                timePlanFromJson(timePlanArray.getJSONObject(it))
            }

            val profile = root.optJSONObject("userProfile")
            userProfile = UserProfile(
                displayName = profile?.optString("displayName", "") ?: ""
            )

            val templateArray = root.optJSONArray("reportTemplates") ?: JSONArray()
            reportTemplates = List(templateArray.length()) {
                templateFromJson(templateArray.getJSONObject(it))
            }
        }
    }

    private fun checklistToJson(value: Checklist): JSONObject =
        JSONObject()
            .put("id", value.id)
            .put("title", value.title)
            .put("memo", value.memo)
            .put("createdAt", value.createdAt)
            .put("updatedAt", value.updatedAt)
            .put("groups", JSONArray().apply {
                value.groups.forEach { group ->
                    put(
                        JSONObject()
                            .put("id", group.id)
                            .put("checklistId", group.checklistId)
                            .put("name", group.name)
                            .put("order", group.order)
                            .put("color", group.color)
                    )
                }
            })
            .put("items", JSONArray().apply {
                value.items.forEach { item ->
                    put(
                        JSONObject()
                            .put("id", item.id)
                            .put("checklistId", item.checklistId)
                            .put("groupId", item.groupId ?: JSONObject.NULL)
                            .put("order", item.order)
                            .put("name", item.name)
                            .put("status", item.status.name)
                            .put("note", item.note)
                            .put("notificationEnabled", item.notificationEnabled)
                            .put("scheduledTimeMinutes", item.scheduledTimeMinutes ?: JSONObject.NULL)
                            .put("notificationSoundUri", item.notificationSoundUri ?: JSONObject.NULL)
                    )
                }
            })
            .put("deletedItems", JSONArray().apply {
                value.deletedItems.forEach { item ->
                    put(
                        JSONObject()
                            .put("id", item.id)
                            .put("checklistId", item.checklistId)
                            .put("groupId", item.groupId ?: JSONObject.NULL)
                            .put("order", item.order)
                            .put("name", item.name)
                            .put("status", item.status.name)
                            .put("note", item.note)
                            .put("notificationEnabled", item.notificationEnabled)
                            .put("scheduledTimeMinutes", item.scheduledTimeMinutes ?: JSONObject.NULL)
                            .put("notificationSoundUri", item.notificationSoundUri ?: JSONObject.NULL)
                    )
                }
            })

    private fun checklistFromJson(value: JSONObject): Checklist {
        val groups = value.optJSONArray("groups") ?: JSONArray()
        val items = value.optJSONArray("items") ?: JSONArray()
        val deletedItems = value.optJSONArray("deletedItems") ?: JSONArray()

        return Checklist(
            id = value.getString("id"),
            title = value.getString("title"),
            memo = value.optString("memo", ""),
            groups = List(groups.length()) { index ->
                val group = groups.getJSONObject(index)
                ChecklistGroup(
                    id = group.getString("id"),
                    checklistId = group.getString("checklistId"),
                    name = group.getString("name"),
                    order = group.getInt("order"),
                    color = group.optString("color", "#6750A4")
                )
            },
            items = List(items.length()) { index ->
                val item = items.getJSONObject(index)
                ChecklistItem(
                    id = item.getString("id"),
                    checklistId = item.getString("checklistId"),
                    groupId = if (item.isNull("groupId")) null
                    else item.getString("groupId"),
                    order = item.getInt("order"),
                    name = item.getString("name"),
                    status = ChecklistStatus.valueOf(
                        item.getString("status")
                    ),
                    note = item.optString("note", ""),
                    notificationEnabled = item.optBoolean("notificationEnabled", false),
                    scheduledTimeMinutes = if (item.isNull("scheduledTimeMinutes")) null
                    else item.optInt("scheduledTimeMinutes"),
                    notificationSoundUri = if (item.isNull("notificationSoundUri")) null
                    else item.optString("notificationSoundUri")
                )
            },
            deletedItems = List(deletedItems.length()) { index ->
                val item = deletedItems.getJSONObject(index)
                ChecklistItem(
                    id = item.getString("id"),
                    checklistId = item.getString("checklistId"),
                    groupId = if (item.isNull("groupId")) null
                    else item.getString("groupId"),
                    order = item.getInt("order"),
                    name = item.getString("name"),
                    status = ChecklistStatus.valueOf(
                        item.getString("status")
                    ),
                    note = item.optString("note", ""),
                    notificationEnabled = item.optBoolean("notificationEnabled", false),
                    scheduledTimeMinutes = if (item.isNull("scheduledTimeMinutes")) null
                    else item.optInt("scheduledTimeMinutes"),
                    notificationSoundUri = if (item.isNull("notificationSoundUri")) null
                    else item.optString("notificationSoundUri")
                )
            },
            createdAt = value.getLong("createdAt"),
            updatedAt = value.getLong("updatedAt")
        )
    }

    private fun timePlanToJson(value: TimePlan): JSONObject =
        JSONObject()
            .put("id", value.id)
            .put("title", value.title)
            .put("memo", value.memo)
            .put("createdAt", value.createdAt)
            .put("updatedAt", value.updatedAt)
            .put("points", JSONArray().apply {
                value.points.forEach { point ->
                    put(
                        JSONObject()
                            .put("id", point.id)
                            .put("planId", point.planId)
                            .put("order", point.order)
                            .put("name", point.name)
                            .put(
                                "timeMinutes",
                                point.timeMinutes ?: JSONObject.NULL
                            )
                    )
                }
            })

    private fun timePlanFromJson(value: JSONObject): TimePlan {
        val points = value.optJSONArray("points") ?: JSONArray()

        return TimePlan(
            id = value.getString("id"),
            title = value.getString("title"),
            memo = value.optString("memo", ""),
            points = List(points.length()) { index ->
                val point = points.getJSONObject(index)
                TimePoint(
                    id = point.getString("id"),
                    planId = point.getString("planId"),
                    order = point.getInt("order"),
                    name = point.getString("name"),
                    timeMinutes = if (point.isNull("timeMinutes")) null
                    else point.getInt("timeMinutes")
                )
            },
            createdAt = value.getLong("createdAt"),
            updatedAt = value.getLong("updatedAt")
        )
    }

    private fun templateToJson(value: ReportTemplate): JSONObject =
        JSONObject()
            .put("id", value.id)
            .put("name", value.name)
            .put("body", value.body)
            .put("order", value.order)
            .put("isDefault", value.isDefault)

    private fun templateFromJson(value: JSONObject): ReportTemplate =
        ReportTemplate(
            id = value.getString("id"),
            name = value.getString("name"),
            body = value.optString("body", ""),
            order = value.getInt("order"),
            isDefault = value.optBoolean("isDefault", false)
        )
}

package com.seolhwa.armyrist.timeplan.v3.data

import android.content.Context
import com.seolhwa.armyrist.data.GuardedSnapshotStore
import com.seolhwa.armyrist.data.reportStorageError
import com.seolhwa.armyrist.notification.TimePlanActionNotificationManager
import com.seolhwa.armyrist.timeplan.domain.RevisedTimePlan
import com.seolhwa.armyrist.timeplan.domain.EventTimeSpec as LegacySpec
import com.seolhwa.armyrist.timeplan.domain.TimeEventKind as LegacyKind
import com.seolhwa.armyrist.timeplan.v3.domain.*
import org.json.JSONArray
import org.json.JSONObject
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.LocalTime
import java.util.UUID

class DateAwareTimePlanRepository(context: Context) {
    private val appContext = context.applicationContext
    private val prefs = appContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
    private val snapshots = GuardedSnapshotStore(
        readRaw = { prefs.getString(KEY, null) },
        writeRaw = { raw ->
            val editor = prefs.edit()
            if (raw == null) editor.remove(KEY) else editor.putString(KEY, raw)
            editor.commit()
        },
        decode = ::decodeSnapshot,
        encode = ::encodeSnapshot,
        onError = { reportStorageError(appContext, it) }
    )
    @Volatile private var plans: List<DateAwareTimePlan> = snapshots.load(emptyList())

    internal val storageReadable: Boolean get() = snapshots.readable

    @Synchronized fun reloadFromPersistence() { plans = snapshots.load(emptyList(), plans) }

    @Synchronized
    fun getPlans(): List<DateAwareTimePlan> {
        val fallback = plans.sortedByDescending { it.updatedAt.toLongOrNull() ?: 0L }
        val storedOrder = loadPlanOrder()
        if (storedOrder.isEmpty()) return fallback

        val byId = plans.associateBy { it.id }
        val ordered = storedOrder.mapNotNull(byId::get)
        val missing = fallback.filter { it.id !in storedOrder.toSet() }
        return ordered + missing
    }

    @Synchronized
    fun movePlan(planId: String, direction: Int): Boolean {
        if (direction == 0) return true
        val displayed = getPlans().toMutableList()
        val from = displayed.indexOfFirst { it.id == planId }
        if (from < 0) return false
        val to = (from + direction).coerceIn(0, displayed.lastIndex)
        if (from == to) return true

        val item = displayed.removeAt(from)
        displayed.add(to, item)
        return savePlanOrder(displayed.map { it.id })
    }

    /**
     * Persists the complete user-visible TimePlan order after drag/drop.
     * Unknown/duplicate IDs are rejected so reorder cannot silently lose plans.
     */
    @Synchronized
    fun setPlanOrder(orderedIds: List<String>): Boolean {
        val currentIds = plans.map { it.id }.toSet()
        if (orderedIds.size != currentIds.size) return false
        if (orderedIds.distinct().size != orderedIds.size) return false
        if (orderedIds.toSet() != currentIds) return false
        return savePlanOrder(orderedIds)
    }

    @Synchronized fun getPlan(id: String): DateAwareTimePlan? = plans.firstOrNull { it.id == id }
    @Synchronized fun contains(id: String): Boolean = plans.any { it.id == id }

    @Synchronized
    fun createPlan(now: LocalDateTime = LocalDateTime.now()): DateAwareTimePlan? {
        val end = now.plusHours(1)
        val plan = DateTimePlanRules.normalizeTopology(
            DateAwareTimePlan(
                id = UUID.randomUUID().toString(),
                title = "새 시간계획",
                start = DateTimeAnchor(DateTimeValue.explicit(now.withSecond(0).withNano(0))),
                end = DateTimeAnchor(DateTimeValue.explicit(end.withSecond(0).withNano(0))),
                createdAt = System.currentTimeMillis().toString(),
                updatedAt = System.currentTimeMillis().toString()
            )
        )
        val next = plans + plan
        if (!persist(next)) return null
        plans = next
        if (loadPlanOrder().isNotEmpty()) {
            savePlanOrder(listOf(plan.id) + getPlans().map { it.id }.filterNot { it == plan.id })
        }
        TimePlanActionNotificationManager.reconcile(appContext, this)
        return plan
    }

    @Synchronized
    fun commit(value: DateAwareTimePlan): Boolean {
        if (value.legacyDateMigrationRequired) return false
        if (DateTimePlanRules.validateForPersistence(value).isNotEmpty()) return false
        val normalized = DateTimePlanRules.normalizeTopology(value)
        val next = if (plans.any { it.id == value.id }) plans.map { if (it.id == value.id) normalized else it } else plans + normalized
        if (!persist(next)) return false
        plans = next
        TimePlanActionNotificationManager.reconcile(appContext, this)
        return true
    }

    @Synchronized fun delete(id: String) {
        val next = plans.filterNot { it.id == id }
        if (persist(next)) {
            plans = next
            val storedOrder = loadPlanOrder()
            if (storedOrder.isNotEmpty()) {
                savePlanOrder(storedOrder.filterNot { it == id })
            }
            runCatching {
                TimePlanActionNotificationManager.reconcile(appContext, this)
            }
        }
    }

    /**
     * Restores a complete TimePlan snapshot that was previously moved to Common Trash.
     *
     * The snapshot originated from this repository, so restore does not reinterpret
     * Point/Action data or run migration guesses. Existing IDs are never overwritten.
     */
    @Synchronized
    fun restoreDeletedPlan(snapshot: DateAwareTimePlan): Boolean {
        if (plans.any { it.id == snapshot.id }) return false

        val restored =
            DateTimePlanRules.normalizeTopology(
                snapshot.copy(
                    updatedAt = System.currentTimeMillis().toString()
                )
            )

        val next = plans + restored
        if (!persist(next)) return false

        plans = next
        if (loadPlanOrder().isNotEmpty()) {
            savePlanOrder(listOf(restored.id) + getPlans().map { it.id }.filterNot { it == restored.id })
        }

        // Restore future notification schedules. Scheduling failure is secondary to
        // successfully restoring the user's local data.
        runCatching {
            TimePlanActionNotificationManager.reconcile(appContext, this)
        }

        return true
    }

    /**
     * Atomically removes one MIDWAY/FINAL event without ever removing the owning plan.
     *
     * UI code must not synthesize and commit a partially-mutated topology during an
     * active edit dialog. The repository owns the complete transaction:
     * current snapshot -> remove event -> remove child actions -> rebuild order/links
     * -> validate -> persist -> publish.
     */
    @Synchronized
    fun deleteEvent(planId: String, eventId: String): Boolean =
        runCatching {
            deleteEventInternal(planId, eventId)
        }.onFailure {
            android.util.Log.e(
                "Armyrist-TimePlan",
                "Atomic event deletion failed plan=$planId event=$eventId",
                it
            )
        }.getOrDefault(false)

    private fun deleteEventInternal(planId: String, eventId: String): Boolean {
        val current = plans.firstOrNull { it.id == planId } ?: return false

        val isFinal = current.finalPoint?.id == eventId
        val isMidway = current.midwayEvents.any { it.id == eventId }
        if (!isFinal && !isMidway) return false

        // Deletion is intentionally implemented as a narrowing transaction.
        // Do not run whole-plan validators here: older plans can legitimately carry
        // unresolved temporal conflicts or legacy Action defects that are unrelated
        // to the point being removed.
        val survivingMidways =
            current.midwayEvents
                .filterNot { it.id == eventId }
                .sortedBy { it.order }
                .mapIndexed { index, event -> event.copy(order = index) }

        val withoutPoint =
            current.copy(
                midwayEvents = survivingMidways,
                finalPoint = if (isFinal) null else current.finalPoint,
                // Old links are discarded completely. They will be rebuilt only
                // from the nodes that survive this transaction.
                links = emptyList(),
                // Child Actions of the removed point are deleted in the same snapshot.
                actions = current.actions.filterNot { it.parentPointId == eventId },
                updatedAt = System.currentTimeMillis().toString()
            )

        val survivingNodeIds = DateTimePlanRules.nodeIds(withoutPoint).toSet()
        val survivingGroupIds = withoutPoint.actionGroups.map { it.id }.toSet()

        // Sanitize only references that cannot survive the delete.
        // Unrelated Action contents/completion/notification state are preserved.
        val sanitized =
            TimePlanExecutionRules.normalizeActionOrder(
                withoutPoint.copy(
                    actions = withoutPoint.actions
                        .filter { it.parentPointId in survivingNodeIds }
                        .map { action ->
                            if (action.groupId != null && action.groupId !in survivingGroupIds) {
                                action.copy(groupId = null)
                            } else {
                                action
                            }
                        }
                )
            )

        val rebuilt =
            DateTimePlanRules.normalizeTopology(
                sanitized.copy(links = emptyList())
            )

        // Persist the complete replacement snapshot once. There are deliberately no
        // additional whole-plan validation gates between reconstruction and persist.
        val next = plans.map { plan ->
            if (plan.id == planId) rebuilt else plan
        }

        if (!persist(next)) {
            android.util.Log.e(
                "Armyrist-TimePlan",
                "MIDWAY delete persist failed plan=$planId event=$eventId"
            )
            return false
        }

        plans = next

        // Alarm reconciliation is secondary. A platform-side scheduling failure must
        // never undo or report failure for an already-persisted point deletion.
        runCatching {
            TimePlanActionNotificationManager.reconcile(appContext, this)
        }.onFailure {
            android.util.Log.e(
                "Armyrist-TimePlan",
                "Post-delete notification reconcile failed plan=$planId event=$eventId",
                it
            )
        }

        return true
    }

    @Synchronized
    fun importAsNew(source: DateAwareTimePlan): String? {
        val fresh = com.seolhwa.armyrist.timeplan.v3.portable.TimePlanPortableV3Codec.regenerateIds(source)
        if (DateTimePlanRules.validateForPersistence(fresh).isNotEmpty()) return null
        val next = plans + DateTimePlanRules.normalizeTopology(fresh)
        if (!persist(next)) return null
        plans = next
        if (loadPlanOrder().isNotEmpty()) {
            savePlanOrder(listOf(fresh.id) + getPlans().map { it.id }.filterNot { it == fresh.id })
        }
        TimePlanActionNotificationManager.reconcile(appContext, this)
        return fresh.id
    }

    @Synchronized
    fun replaceAll(restored: List<DateAwareTimePlan>): Boolean {
        if (restored.any { DateTimePlanRules.validateForPersistence(it).isNotEmpty() }) return false
        val next = restored.map(DateTimePlanRules::normalizeTopology)
        if (!persist(next)) return false
        plans = next
        savePlanOrder(next.map { it.id })
        TimePlanActionNotificationManager.reconcile(appContext, this)
        return true
    }

    fun exportSnapshot(): String {
        check(snapshots.readable) { "Cannot export unreadable TimePlan data." }
        return JSONObject()
        .put("schemaVersion", SCHEMA)
        .put("plans", JSONArray().apply { getPlans().forEach { put(DateAwareTimePlanJson.encode(it)) } })
        .toString()
    }

    /**
     * User-confirmed atomic legacy date migration. No persistence happens before the candidate validates.
     */
    @Synchronized
    fun migrateLegacy(legacy: RevisedTimePlan, baseDate: LocalDate): DateAwareTimePlan? {
        val candidate = LegacyDateMigration.createCandidate(legacy, baseDate) ?: return null
        if (DateTimePlanRules.validateForPersistence(candidate).isNotEmpty()) return null
        val normalized = DateTimePlanRules.normalizeTopology(candidate)
        val next = plans.filterNot { it.id == normalized.id } + normalized
        if (!persist(next)) return null
        plans = next
        TimePlanActionNotificationManager.reconcile(appContext, this)
        return normalized
    }

    private fun persist(values: List<DateAwareTimePlan>): Boolean = snapshots.save(values)

    private fun encodeSnapshot(values: List<DateAwareTimePlan>): String = JSONObject()
        .put("schemaVersion", SCHEMA)
        .put("plans", JSONArray().apply { values.forEach { put(DateAwareTimePlanJson.encode(it)) } })
        .toString()

    private fun decodeSnapshot(raw: String): List<DateAwareTimePlan> {
        val root = JSONObject(raw)
        require(root.getInt("schemaVersion") in setOf(3, 4, SCHEMA))
        val array = root.getJSONArray("plans")
        return List(array.length()) { DateAwareTimePlanJson.decode(array.getJSONObject(it)) }
    }

    private fun loadPlanOrder(): List<String> =
        prefs.getString(KEY_PLAN_ORDER, null)
            ?.split('|')
            ?.map(String::trim)
            ?.filter(String::isNotEmpty)
            .orEmpty()

    private fun savePlanOrder(ids: List<String>): Boolean =
        prefs.edit()
            .putString(KEY_PLAN_ORDER, ids.distinct().joinToString("|"))
            .commit()

    companion object {
        const val PREFS = "armyrist_timeplan_v3"
        const val KEY = "snapshot_v3"
        const val KEY_PLAN_ORDER = "plan_order_v1"
        const val SCHEMA = 5
    }
}

object LegacyDateMigration {
    fun createCandidate(legacy: RevisedTimePlan, baseDate: LocalDate): DateAwareTimePlan? {
        var currentDate = baseDate
        var previousClock: Int? = null
        fun resolve(clockMinute: Int?): LocalDateTime? {
            if (clockMinute == null) return null
            if (previousClock != null && clockMinute < previousClock!!) currentDate = currentDate.plusDays(1)
            previousClock = clockMinute
            return LocalDateTime.of(currentDate, LocalTime.of(clockMinute / 60, clockMinute % 60))
        }
        fun value(v: com.seolhwa.armyrist.timeplan.domain.ClockValue): DateTimeValue =
            v.time?.minuteOfDay?.let { minute ->
                DateTimeValue(resolve(minute), when (v.origin) {
                    com.seolhwa.armyrist.timeplan.domain.ValueOrigin.EXPLICIT -> ValueOrigin.EXPLICIT
                    com.seolhwa.armyrist.timeplan.domain.ValueOrigin.DERIVED -> ValueOrigin.DERIVED
                    com.seolhwa.armyrist.timeplan.domain.ValueOrigin.UNSET -> ValueOrigin.UNSET
                })
            } ?: DateTimeValue.unset()
        fun spec(s: LegacySpec): EventDateTimeSpec = when (s) {
            LegacySpec.Unspecified -> EventDateTimeSpec.Unspecified
            is LegacySpec.Single -> EventDateTimeSpec.Single(value(s.value))
            is LegacySpec.Range -> EventDateTimeSpec.Range(value(s.start), value(s.end))
        }
        val start = value(legacy.start.value)
        val mids = legacy.midwayEvents.sortedBy { it.order }.map { e ->
            DateTimeEvent(e.id, TimeEventKind.MIDWAY, e.order, e.name, spec(e.timeSpec), e.note)
        }
        val final = legacy.finalPoint?.let { e ->
            DateTimeEvent(e.id, TimeEventKind.FINAL, mids.size, e.name, spec(e.timeSpec), e.note)
        }
        val end = value(legacy.end.value)
        val nodeIds = buildList { add(DateTimePlanRules.START_ID); addAll(mids.map { it.id }); final?.let { add(it.id) }; add(DateTimePlanRules.END_ID) }
        val legacyLinks = legacy.links.associateBy { it.fromNodeId to it.toNodeId }
        val links = nodeIds.zipWithNext().map { (from,to) ->
            val l = legacyLinks[from to to]
            DateTimeLink(
                from, to,
                l?.duration?.minutes?.toLong(),
                when (l?.origin) {
                    com.seolhwa.armyrist.timeplan.domain.ValueOrigin.EXPLICIT -> ValueOrigin.EXPLICIT
                    com.seolhwa.armyrist.timeplan.domain.ValueOrigin.DERIVED -> ValueOrigin.DERIVED
                    else -> ValueOrigin.UNSET
                },
                l?.label
            )
        }
        return DateAwareTimePlan(
            id = legacy.id,
            title = legacy.title,
            start = DateTimeAnchor(start),
            midwayEvents = mids,
            finalPoint = final,
            end = DateTimeAnchor(end),
            links = links,
            memo = legacy.memo,
            createdAt = legacy.createdAt,
            updatedAt = System.currentTimeMillis().toString(),
            legacyDateMigrationRequired = false
        )
    }
}

object DateAwareTimePlanJson {
    fun encode(p: DateAwareTimePlan): JSONObject = JSONObject()
        .put("schemaVersion", 6).put("id", p.id).put("title", p.title)
        .put("dateDisplayMode", p.dateDisplayMode.name)
        .put("start", valueToJson(p.start.value).put("dateTimeLocked", p.start.dateTimeLocked))
        .put("midwayEvents", JSONArray().apply { p.midwayEvents.sortedBy { it.order }.forEach { put(eventToJson(it)) } })
        .put("finalPoint", p.finalPoint?.let(::eventToJson) ?: JSONObject.NULL)
        .put("end", valueToJson(p.end.value).put("dateTimeLocked", p.end.dateTimeLocked))
        .put("links", JSONArray().apply { p.links.forEach { put(linkToJson(it)) } })
        .put("actionGroups", JSONArray().apply { p.actionGroups.sortedBy { it.order }.forEach { put(actionGroupToJson(it)) } })
        .put("actions", JSONArray().apply { p.actions.sortedWith(compareBy<TimePlanActionItem> { it.parentPointId }.thenBy { it.order }).forEach { put(actionToJson(it)) } })
        .put("memo", p.memo ?: JSONObject.NULL)
        .put("createdAt", p.createdAt).put("updatedAt", p.updatedAt)

    fun decode(j: JSONObject): DateAwareTimePlan {
        val schema = j.getInt("schemaVersion")
        require(schema in setOf(3, 4, 5, 6))
        val mids = j.optJSONArray("midwayEvents") ?: JSONArray()
        val links = j.optJSONArray("links") ?: JSONArray()
        val actionGroups = j.optJSONArray("actionGroups") ?: JSONArray()
        val actions = j.optJSONArray("actions") ?: JSONArray()
        return DateAwareTimePlan(
            id=j.getString("id"), title=j.getString("title"),
            start=j.getJSONObject("start").let { a ->
                DateTimeAnchor(valueFromJson(a), a.optBoolean("dateTimeLocked", false))
            },
            midwayEvents=List(mids.length()){ eventFromJson(mids.getJSONObject(it)) },
            finalPoint=if(j.isNull("finalPoint")) null else eventFromJson(j.getJSONObject("finalPoint")),
            end=j.getJSONObject("end").let { a ->
                DateTimeAnchor(valueFromJson(a), a.optBoolean("dateTimeLocked", false))
            },
            links=List(links.length()){ linkFromJson(links.getJSONObject(it)) },
            actionGroups=List(actionGroups.length()){ actionGroupFromJson(actionGroups.getJSONObject(it)) },
            actions=List(actions.length()){ actionFromJson(actions.getJSONObject(it)) },
            memo=if(j.isNull("memo")) null else j.getString("memo"),
            createdAt=j.getString("createdAt"), updatedAt=j.getString("updatedAt"),
            dateDisplayMode = runCatching { TimePlanDateDisplayMode.valueOf(j.optString("dateDisplayMode", TimePlanDateDisplayMode.ABSOLUTE.name)) }.getOrDefault(TimePlanDateDisplayMode.ABSOLUTE)
        )
    }
    private fun valueToJson(v: DateTimeValue)=JSONObject().put("dateTime",v.value?.toString()?:JSONObject.NULL).put("origin",v.origin.name)
    private fun valueFromJson(j:JSONObject)=if(j.isNull("dateTime")) DateTimeValue.unset() else DateTimeValue(LocalDateTime.parse(j.getString("dateTime")),ValueOrigin.valueOf(j.getString("origin")))
    private fun specToJson(s:EventDateTimeSpec):JSONObject=when(s){
        EventDateTimeSpec.Unspecified->JSONObject().put("type","UNSPECIFIED")
        is EventDateTimeSpec.Single->JSONObject().put("type","SINGLE").put("value",valueToJson(s.value))
        is EventDateTimeSpec.Range->JSONObject().put("type","RANGE").put("start",valueToJson(s.start)).put("end",valueToJson(s.end))
    }
    private fun specFromJson(j:JSONObject):EventDateTimeSpec=when(j.getString("type")){
        "UNSPECIFIED"->EventDateTimeSpec.Unspecified
        "SINGLE"->EventDateTimeSpec.Single(valueFromJson(j.getJSONObject("value")))
        "RANGE"->EventDateTimeSpec.Range(valueFromJson(j.getJSONObject("start")),valueFromJson(j.getJSONObject("end")))
        else->error("unsupported spec")
    }
    private fun eventToJson(e:DateTimeEvent)=JSONObject()
        .put("id",e.id).put("kind",e.kind.name).put("order",e.order).put("name",e.name)
        .put("timeSpec",specToJson(e.timeSpec)).put("note",e.note?:JSONObject.NULL)
        .put("dateTimeLocked", e.dateTimeLocked)
    private fun eventFromJson(j:JSONObject)=DateTimeEvent(
        j.getString("id"), TimeEventKind.valueOf(j.getString("kind")), j.getInt("order"),
        j.getString("name"), specFromJson(j.getJSONObject("timeSpec")),
        if(j.isNull("note")) null else j.getString("note"),
        j.optBoolean("dateTimeLocked", false)
    )
    private fun linkToJson(l:DateTimeLink)=JSONObject()
        .put("fromNodeId",l.fromNodeId).put("toNodeId",l.toNodeId)
        .put("minutes",l.durationMinutes?:JSONObject.NULL).put("origin",l.origin.name)
        .put("label",l.label?:JSONObject.NULL).put("durationLocked", l.durationLocked)
    private fun linkFromJson(j:JSONObject)=DateTimeLink(
        j.getString("fromNodeId"), j.getString("toNodeId"),
        if(j.isNull("minutes")) null else j.getLong("minutes"),
        ValueOrigin.valueOf(j.getString("origin")),
        if(j.isNull("label")) null else j.getString("label"),
        j.optBoolean("durationLocked", false)
    )
    private fun actionGroupToJson(g: TimePlanActionGroup) = JSONObject()
        .put("id", g.id).put("name", g.name).put("order", g.order).put("color", g.color)
    private fun actionGroupFromJson(j: JSONObject) = TimePlanActionGroup(
        id = j.getString("id"),
        name = j.getString("name"),
        order = j.getInt("order"),
        color = j.optString("color", "#7A7D61")
    )
    private fun actionToJson(a: TimePlanActionItem) = JSONObject()
        .put("id", a.id)
        .put("parentPointId", a.parentPointId)
        .put("content", a.content)
        .put("scheduledDateTime", a.scheduledDateTime.toString())
        .put("completionState", a.completionState.name)
        .put("notificationEnabled", a.notificationMode != ActionNotificationMode.NONE)
        .put("notificationMode", a.notificationMode.name)
        .put("groupId", a.groupId ?: JSONObject.NULL)
        .put("note", a.note ?: JSONObject.NULL)
        .put("order", a.order)
        .put("createdAt", a.createdAt)
        .put("updatedAt", a.updatedAt)
    private fun actionFromJson(j: JSONObject) = TimePlanActionItem(
        id = j.getString("id"),
        parentPointId = j.getString("parentPointId"),
        content = j.getString("content"),
        scheduledDateTime = LocalDateTime.parse(j.getString("scheduledDateTime")),
        completionState = ActionCompletionState.valueOf(j.optString("completionState", ActionCompletionState.INCOMPLETE.name)),
        notificationEnabled = j.optBoolean("notificationEnabled", false),
        notificationMode = runCatching { ActionNotificationMode.valueOf(j.optString("notificationMode")) }.getOrElse { if (j.optBoolean("notificationEnabled", false)) ActionNotificationMode.SIMPLE else ActionNotificationMode.NONE },
        groupId = if (j.isNull("groupId")) null else j.getString("groupId"),
        note = if (j.isNull("note")) null else j.getString("note"),
        order = j.optInt("order", 0),
        createdAt = j.optString("createdAt", System.currentTimeMillis().toString()),
        updatedAt = j.optString("updatedAt", System.currentTimeMillis().toString())
    )
}

