    fun visiblePlansForFolder(): List<DateAwareTimePlan> {
        val currentFolder = openedFolder
        return if (currentFolder == null) {
            orderedPlans.filter { memberToFolder[it.id] == null }
        } else {
            val byId = orderedPlans.associateBy { it.id }
            val order =
                if (folderVisualOrder.isNotEmpty()) folderVisualOrder
                else currentFolder.memberIds
            order.mapNotNull(byId::get)
        }
    }

    fun reorderPlanAtFinger(planId: String): Boolean {
        val layout = listState.layoutInfo
        val cardKey = "v3-$planId"
        val draggedInfo =
            layout.visibleItemsInfo.firstOrNull { it.key == cardKey } ?: return false

        val draggedCenter =
            draggedInfo.offset + draggedInfo.size / 2f + dragOffsetY

        val target = layout.visibleItemsInfo
            .filter {
                it.key is String &&
                    (it.key as String).startsWith("v3-") &&
                    it.key != cardKey
            }
            .minByOrNull {
                kotlin.math.abs(
                    (it.offset + it.size / 2f) - draggedCenter
                )
            } ?: return false

        val targetId = (target.key as String).removePrefix("v3-")
        val folderMode = openedFolder != null
        val fromIndex =
            if (folderMode) folderVisualOrder.indexOf(planId)
            else orderedPlans.indexOfFirst { it.id == planId }
        val targetIndex =
            if (folderMode) folderVisualOrder.indexOf(targetId)
            else orderedPlans.indexOfFirst { it.id == targetId }

        if (fromIndex < 0 || targetIndex < 0 || fromIndex == targetIndex) return false

        val crossed =
            if (targetIndex > fromIndex) {
                draggedCenter > target.offset + target.size * 0.48f
            } else {
                draggedCenter < target.offset + target.size * 0.52f
            }
        if (!crossed) return false
        if ((targetIndex > fromIndex) != (target.offset > draggedInfo.offset)) return false

        val oldOffset = draggedInfo.offset
        val targetOffset = target.offset

        if (folderMode) {
            val movedId = folderVisualOrder.removeAt(fromIndex)
            folderVisualOrder.add(targetIndex, movedId)
        } else {
            val moved = orderedPlans.removeAt(fromIndex)
            orderedPlans.add(targetIndex, moved)
        }

        // Cancel the layout jump of the dragged card.
        dragOffsetY += DragMotion.compensation(
            oldOffset, draggedInfo.size, targetOffset, target.size, targetIndex > fromIndex
        )
        reorderDirty = true
        return true
    }

    fun finishFolderReorder(commit: Boolean) {
        if (commit && folderReorderDirty) {
            if (
                collectionRepository.replaceFolderOrder(
                    CollectionToolType.TIME_PLAN,
                    folderVisualList.map { it.id }
                )
            ) {
                collectionRevision++
            }
        } else if (!commit) {
            folderVisualList.clear()
            folderVisualList.addAll(folders)
        }
        draggingFolderId = null
        folderDragOffsetY = 0f
        folderReorderDirty = false
    }

    fun finishReorder(commit: Boolean) {
        val currentFolder = openedFolder
        if (commit && reorderDirty) {
            if (currentFolder != null) {
                if (
                    collectionRepository.replaceMemberOrder(
                        currentFolder.id,
                        folderVisualOrder.toList()
                    )
                ) {
                    collectionRevision++
                }
            } else {
                onOrderChanged(orderedPlans.map { it.id })
            }
        } else if (!commit) {
            if (currentFolder != null) {
                folderVisualOrder.clear()
                folderVisualOrder.addAll(currentFolder.memberIds)
            } else {
                orderedPlans.clear()
                orderedPlans.addAll(datePlans)
            }
        }
        draggingPlanId = null
        dragAutoScrollDirection = 0
        dragAutoScrollStepPx = 0f
        dragOffsetY = 0f
        reorderDirty = false
    }

    LaunchedEffect(draggingPlanId) {
        var previousFrame = 0L
        while (draggingPlanId != null) {
            val frame = withFrameNanos { it }
            val scale = DragMotion.frameScale(previousFrame, frame)
            previousFrame = frame
            if (dragAutoScrollDirection != 0) {
                val consumed = listState.scrollBy(dragAutoScrollStepPx * scale)
                dragOffsetY += consumed
            }
            draggingPlanId?.let { reorderPlanAtFinger(it) }
        }
    }

