                                                            ((autoScrollThresholdPx - topDistance) /
                                                                autoScrollThresholdPx)
                                                                .coerceIn(0f, 1f)
                                                        -maxAutoScrollPx * intensity
                                                    }
                                                    bottomDistance < autoScrollThresholdPx -> {
                                                        val intensity =
                                                            ((autoScrollThresholdPx - bottomDistance) /
                                                                autoScrollThresholdPx)
                                                                .coerceIn(0f, 1f)
                                                        maxAutoScrollPx * intensity
                                                    }
                                                    else -> 0f
                                                }

