/** Pointer movement only changes this local projection. A changed drop emits one order. */
@Stable
internal class IdReorderDraft(initial: List<String>) {
    var order: List<String> by mutableStateOf(initial.toList())
        private set
    var draggingId: String? by mutableStateOf(null)
        private set
    private var original = order

    fun sync(ids: List<String>) {
        if (draggingId == null && order != ids) order = ids.toList()
    }

    fun begin(id: String): Boolean {
        if (id !in order || draggingId != null) return false
        original = order
        draggingId = id
        return true
    }

    fun moveTo(targetIndex: Int): Boolean {
        val from = order.indexOf(draggingId)
        if (from < 0) return false
        val to = targetIndex.coerceIn(0, order.lastIndex)
        if (from == to) return false
        order = order.toMutableList().apply { add(to, removeAt(from)) }
        return true
    }

    fun finish(commit: Boolean): List<String>? {
        if (draggingId == null) return null
        draggingId = null
        val changed = order != original
        if (!commit) order = original
        return if (commit && changed) order.toList() else null
    }
}

internal fun <T> reorderedByIds(items: List<T>, ids: List<String>, idOf: (T) -> String): List<T>? {
    val byId = items.associateBy(idOf)
    if (byId.size != items.size || ids.size != items.size || ids.toSet().size != ids.size) return null
    if (ids.toSet() != byId.keys) return null
    return ids.map { byId.getValue(it) }
}

package com.seolhwa.armyrist.ui

internal object DragMotion {
    /** Keep the grabbed point stationary even when neighbouring rows have different heights. */
    fun compensation(fromOffset: Int, fromSize: Int, toOffset: Int, toSize: Int, movingDown: Boolean): Float {
        val destination = if (movingDown) toOffset + toSize - fromSize else toOffset
        return (fromOffset - destination).toFloat()
    }

    /** Existing drag speeds are specified per 60 Hz frame; use actual frame time. */
    fun frameScale(previousNanos: Long, nowNanos: Long): Float =
        if (previousNanos <= 0L || nowNanos <= previousNanos) 0f
        else ((nowNanos - previousNanos).coerceAtMost(50_000_000L) / 16_666_667f)
}

package com.seolhwa.armyrist.data

/** Publishes no replacement data when loading or committing a snapshot fails. */
internal class GuardedSnapshotStore<T>(
    private val readRaw: () -> String?,
    private val writeRaw: (String?) -> Boolean,
    private val decode: (String) -> T,
    private val encode: (T) -> String,
    private val onError: (String) -> Unit
) {
    var readable: Boolean = true
        private set
    private var verifiedRaw: String? = null
    private var hasVerifiedRaw = false

    fun load(emptyValue: T, previousValue: T = emptyValue): T = try {
        val raw = readRaw()
        val value = if (raw == null) emptyValue else decode(raw)
        verifiedRaw = raw
        hasVerifiedRaw = true
        readable = true
        value
    } catch (_: Exception) {
        readable = false
        onError("저장 데이터를 읽을 수 없습니다. 원본을 보호하기 위해 수정을 중지했습니다. 데이터 관리에서 백업을 복원해주세요.")
        previousValue
    }

    fun save(value: T): Boolean {
        if (!readable) {
            onError("저장 원본을 보호하고 있습니다. 백업 복원 후 다시 시도해주세요.")
            return false
        }
        val previous: String?
        try {
            previous = readRaw()
            // Also protect against corruption introduced since the last load.
            if (previous != null && (!hasVerifiedRaw || previous != verifiedRaw)) decode(previous)
        } catch (_: Exception) {
            readable = false
            onError("저장 데이터가 손상되어 변경하지 않았습니다. 백업을 복원해주세요.")
            return false
        }
        var encoded: String? = null
        val success = try {
            encoded = encode(value)
            writeRaw(encoded)
        } catch (_: Exception) { false }
        if (success) {
            verifiedRaw = encoded
            hasVerifiedRaw = true
        }
        if (!success) {
            // SharedPreferences updates its memory even when its disk commit fails.
            // Restore that memory too, so a later reader cannot publish failed edits.
            runCatching { writeRaw(previous) }
            onError("저장하지 못했습니다. 저장 공간을 확인한 뒤 다시 시도해주세요.")
        }
        return success
    }
}

