package com.seolhwa.armyrist.collection

internal object ThumbnailSizing {
    fun sampleSize(width: Int, height: Int, targetPixels: Int): Int {
        require(width > 0 && height > 0 && targetPixels > 0)
        var sample = 1
        // Keep at most twice the requested longest edge before the final resize.
        while (sample <= Int.MAX_VALUE / 2 && maxOf(width, height) / sample / 2 >= targetPixels) sample *= 2
        return sample
    }
}

package com.seolhwa.armyrist.collection

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.LruCache
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Semaphore
import kotlinx.coroutines.sync.withPermit
import kotlinx.coroutines.withContext
import java.io.File

internal object FolderThumbnailLoader {
    private val cache = object : LruCache<String, Bitmap>(4 * 1024 * 1024) {
        override fun sizeOf(key: String, value: Bitmap): Int = value.allocationByteCount
    }
    private val decoders = Semaphore(2)

    fun cached(path: String, requestedPixels: Int): Bitmap? = cache.get("$path@${requestedPixels.coerceIn(1, 512)}")

    suspend fun load(path: String, requestedPixels: Int): Bitmap? = withContext(Dispatchers.IO) {
        val pixels = requestedPixels.coerceIn(1, 512)
        val key = "$path@$pixels"
        cache.get(key)?.let { return@withContext it }
        decoders.withPermit {
            cache.get(key)?.let { return@withPermit it }
            runCatching {
                if (!File(path).isFile) return@runCatching null
                val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                BitmapFactory.decodeFile(path, bounds)
                if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return@runCatching null
                val options = BitmapFactory.Options().apply {
                    inSampleSize = ThumbnailSizing.sampleSize(bounds.outWidth, bounds.outHeight, pixels)
                }
                val decoded = BitmapFactory.decodeFile(path, options) ?: return@runCatching null
                val ratio = minOf(1f, pixels.toFloat() / maxOf(decoded.width, decoded.height))
                val thumbnail = if (ratio < 1f) Bitmap.createScaledBitmap(
                    decoded, maxOf(1, (decoded.width * ratio).toInt()), maxOf(1, (decoded.height * ratio).toInt()), true
                ).also { if (it !== decoded) decoded.recycle() } else decoded
                cache.put(key, thumbnail)
                thumbnail
            }.getOrNull()
        }
    }
}

package com.seolhwa.armyrist.counting.reorder

import kotlin.math.min

/** Geometry in the stable drag host, independent of LazyColumn key anchoring. */
internal object CountingDragGeometry {
    fun hostY(itemOffset: Int, beforeContentPadding: Int): Float =
        (itemOffset + beforeContentPadding).toFloat()

    fun overlayTop(pointerY: Float, grabOffsetY: Float): Float = pointerY - grabOffsetY

    /** Signed fraction of maximum scroll speed. At least 60% stays neutral. */
    fun edgeScrollFraction(pointerY: Float, viewportHeight: Float, requestedEdge: Float): Float {
        if (!pointerY.isFinite() || viewportHeight <= 0f || requestedEdge <= 0f) return 0f
        val band = min(requestedEdge, viewportHeight * 0.2f)
        val depth = when {
            pointerY < band -> -((band - pointerY) / band).coerceIn(0f, 1f)
            pointerY > viewportHeight - band -> ((pointerY - viewportHeight + band) / band).coerceIn(0f, 1f)
            else -> 0f
        }
        return depth * kotlin.math.abs(depth)
    }

    /** One adjacent step in the actual pointer/scroll direction, never a remote slot. */
    fun adjacentTarget(
        fromIndex: Int,
        heldCenterY: Float,
        heldHeight: Float,
        direction: Int,
        slots: List<CountingReorderSlot>
    ): Int? {
        if (direction == 0 || fromIndex < 0) return null
        val step = if (direction > 0) 1 else -1
        val neighbour = slots.firstOrNull { it.index == fromIndex + step } ?: return null
        val hysteresis = min(heldHeight, neighbour.height) * 0.08f
        val crossed = if (step > 0) heldCenterY > neighbour.centerY + hysteresis
            else heldCenterY < neighbour.centerY - hysteresis
        return neighbour.index.takeIf { crossed }
    }
}

