        draft.begin("a"); draft.moveTo(2); draft.sync(original)
        assertEquals(listOf("b", "c", "a", "d"), draft.order)
    }
    @Test fun failedSaveCanRestoreCanonicalOrder() {
        val draft = IdReorderDraft(original)
